#### Next.js API Route Example

```typescript
// app/api/notion/databases/schema/route.ts
import { NextRequest, NextResponse } from 'next/server';
import { z } from 'zod';
import { notionClient } from '@/lib/external/notion/api';

// Input validation schema
const QuerySchema = z.object({
  database: z.string(),
});

export async function GET(request: NextRequest) {
  // Get query parameters
  const { searchParams } = new URL(request.url);
  const params = {
    database: searchParams.get('database'),
  };

  // Validate input
  const result = QuerySchema.safeParse(params);
  if (!result.success) {
    return NextResponse.json(
      { error: 'Missing database parameter' },
      { status: 400 }
    );
  }

  const { database } = result.data;
  const dbId = process.env[database];

  if (!dbId) {
    return NextResponse.json(
      {
        error: `Unknown database: ${database}`,
        message: `Ensure ${database} is defined as an environment variable`
      },
      { status: 400 }
    );
  }

  try {
    const schema = await notionClient.retrieveDatabase(dbId);
    return NextResponse.json({ database, schema });
  } catch (err) {
    console.error(`Error retrieving schema for ${database}:`, err);
    return NextResponse.json(
      {
        error: 'Failed to retrieve schema',
        message: err.message
      },
      { status: 500 }
    );
  }
}
```

