/**
 * Helper function to create random embeddings of specified dimension
 * @param dimension The dimension of the embedding vector
 * @returns A random embedding vector
 */
function createRandomEmbedding(dimension: number): number[] {
  return Array.from({ length: dimension }, () => Math.random());
}

/**
 * Helper function to compare two embedding vectors
 * @param vec1 First vector
 * @param vec2 Second vector
 * @param tolerance Tolerance for floating point comparison
 * @returns True if the vectors are approximately equal
 */
function compareEmbeddings(vec1: number[], vec2: number[], tolerance = 0.00001): boolean {
  if (vec1.length !== vec2.length) return false;

  return vec1.every((val, idx) => {
    return Math.abs(val - vec2[idx]) < tolerance;
  });
}

