/**
 * ChromaDB Testing Utilities
 * 
 * This file contains helper functions and utilities for testing ChromaDB integration.
 * These utilities can be used across test files to avoid code duplication and
 * maintain consistency in testing approach.
 */

import { ChromaClient, Collection, Embedding, Metadata } from 'chromadb';
import { v4 as uuidv4 } from 'uuid';
import * as fs from 'fs';
import * as path from 'path';
import dotenv from 'dotenv';

// Load environment variables
dotenv.config();

// Configuration constants
export const DEFAULT_EMBEDDING_DIM = 384; // Common for many embedding models
export const DEFAULT_TEST_COLLECTION = 'test_collection';
export const CHROMA_URL = process.env.CHROMA_URL || 'http://localhost:8000';

/**
 * Interface for a test document
 */
export interface TestDocument {
  id: string;
  text: string;
  metadata: Record<string, any>;
  embedding?: number[];
}

/**
 * Create a ChromaDB client for testing
 * @returns A configured ChromaDB client
 */
export async function createTestClient(): Promise<ChromaClient> {
  return new ChromaClient({ path: CHROMA_URL });
}

/**
 * Create a test collection with optional custom name
 * @param client ChromaDB client
 * @param collectionName Optional collection name
 * @param deleteIfExists Whether to delete the collection if it exists
 * @returns The created collection
 */
export async function createTestCollection(
  client: ChromaClient,
  collectionName: string = DEFAULT_TEST_COLLECTION,
  deleteIfExists: boolean = true
): Promise<Collection> {
  // Check if collection exists
  const collections = await client.listCollections();
  const existingCollection = collections.find(col => col.name === collectionName);

  if (existingCollection && deleteIfExists) {
    await client.deleteCollection({ name: collectionName });
  } else if (existingCollection) {
    return client.getCollection({ name: collectionName });
  }

  // Create a new collection
  return client.createCollection({
    name: collectionName,
    metadata: {
      description: 'Test collection',
      environment: 'test',
      created: new Date().toISOString()
    }
  });
}

/**
 * Create a random embedding vector of specified dimension
 * @param dimension Vector dimension
 * @returns Random embedding vector
 */
export function createRandomEmbedding(dimension: number = DEFAULT_EMBEDDING_DIM): number[] {
  return Array.from({ length: dimension }, () => Math.random());
}

/**
 * Calculate cosine similarity between two vectors
 * @param vec1 First vector
 * @param vec2 Second vector
 * @returns Cosine similarity (-1 to 1, higher is more similar)
 */
export function cosineSimilarity(vec1: number[], vec2: number[]): number {
  if (vec1.length !== vec2.length) {
    throw new Error('Vectors must have the same dimension');
  }

  let dotProduct = 0;
  let mag1 = 0;
  let mag2 = 0;

  for (let i = 0; i < vec1.length; i++) {
    dotProduct += vec1[i] * vec2[i];
    mag1 += vec1[i] * vec1[i];
    mag2 += vec2[i] * vec2[i];
  }

  mag1 = Math.sqrt(mag1);
  mag2 = Math.sqrt(mag2);

  if (mag1 === 0 || mag2 === 0) {
    return 0; // Handle zero vectors
  }

  return dotProduct / (mag1 * mag2);
}

/**
 * Check if two embedding vectors are approximately equal
 * @param vec1 First vector
 * @param vec2 Second vector
 * @param tolerance Tolerance for comparison
 * @returns Whether the vectors are approximately equal
 */
export function areEmbeddingsEqual(
  vec1: number[],
  vec2: number[],
  tolerance: number = 0.00001
): boolean {
  if (vec1.length !== vec2.length) return false;

  return vec1.every((val, idx) => {
    return Math.abs(val - vec2[idx]) < tolerance;
  });
}

/**
 * Create test documents with metadata and optional embeddings
 * @param count Number of documents to create
 * @param prefix Prefix for document IDs
 * @param withEmbeddings Whether to include embeddings
 * @returns Array of test documents
 */
export function createTestDocuments(
  count: number = 5,
  prefix: string = 'test-doc',
  withEmbeddings: boolean = false
): TestDocument[] {
  return Array.from({ length: count }, (_, i) => {
    const doc: TestDocument = {
      id: `${prefix}-${i}`,
      text: `This is test document ${i} for ChromaDB testing.`,
      metadata: {
        source: 'test-suite',
        category: i % 2 === 0 ? 'even' : 'odd',
        importance: (i + 1) * 10,
        created: new Date().toISOString()
      }
    };

    if (withEmbeddings) {
      doc.embedding = createRandomEmbedding();
    }

    return doc;
  });
}

/**
 * Load test data from JSON file
 * @param filePath Path to JSON file
 * @returns Loaded test data
 */
export function loadTestData(filePath: string): any {
  const data = fs.readFileSync(filePath, 'utf8');
  return JSON.parse(data);
}

/**
 * Clean up test collection after tests
 * @param client ChromaDB client
 * @param collectionName Collection name
 */
export async function cleanupTestCollection(
  client: ChromaClient,
  collectionName: string = DEFAULT_TEST_COLLECTION
): Promise<void> {
  try {
    await client.deleteCollection({ name: collectionName });
  } catch (error) {
    console.error(`Error deleting collection ${collectionName}:`, error);
  }
}

/**
 * Wait for a specified time
 * @param ms Milliseconds to wait
 * @returns Promise that resolves after delay
 */
export function delay(ms: number): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms));
}

/**
 * Check if an object is in the expected format
 * @param obj Object to check
 * @param expectedFormat Expected format object
 * @returns Whether the object matches the expected format
 */
export function matchesFormat(obj: any, expectedFormat: any): boolean {
  // Check if obj is undefined when it shouldn't be
  if (obj === undefined && expectedFormat !== undefined) {
    return false;
  }

  // Handle primitive types
  if (typeof expectedFormat !== 'object' || expectedFormat === null) {
    return typeof obj === typeof expectedFormat;
  }

  // Handle arrays
  if (Array.isArray(expectedFormat)) {
    if (!Array.isArray(obj)) return false;
    if (expectedFormat.length === 0) return true; // Empty array format matches any array
    if (expectedFormat.length === 1) {
      // Array with one element defines the expected format for all elements
      return obj.every(item => matchesFormat(item, expectedFormat[0]));
    }

    // If the expected format has multiple elements, the obj should match those exactly
    if (obj.length !== expectedFormat.length) return false;
    return obj.every((item, idx) => matchesFormat(item, expectedFormat[idx]));
  }

  // Handle objects
  if (!obj || typeof obj !== 'object') return false;

  for (const key in expectedFormat) {
    if (!matchesFormat(obj[key], expectedFormat[key])) {
      return false;
    }
  }

  return true;
}

/**
 * Helper for batch operations with ChromaDB
 * @param items Items to process in batches
 * @param batchSize Size of each batch
 * @param processBatch Function to process each batch
 */
export async function processBatches<T, R>(
  items: T[],
  batchSize: number,
  processBatch: (batch: T[]) => Promise<R>
): Promise<R[]> {
  const results: R[] = [];

  for (let i = 0; i < items.length; i += batchSize) {
    const batch = items.slice(i, i + batchSize);
    const result = await processBatch(batch);
    results.push(result);
  }

  return results;
}

/**
 * Generate a mock embedding function for testing
 * @param dimension Embedding dimension
 * @returns Function that generates consistent embeddings for the same input
 */
export function createMockEmbeddingFunction(dimension: number = DEFAULT_EMBEDDING_DIM) {
  // Simple hash function to get consistent embeddings for the same input
  function simpleHash(text: string): number {
    let hash = 0;
    for (let i = 0; i < text.length; i++) {
      const char = text.charCodeAt(i);
      hash = ((hash << 5) - hash) + char;
      hash = hash & hash; // Convert to 32bit integer
    }
    return hash;
  }

  return function(texts: string[]): number[][] {
    return texts.map(text => {
      const seed = simpleHash(text);
      // Use the seed to generate a deterministic embedding
      return Array.from({ length: dimension }, (_, i) => {
        // Use a simple algorithm to generate a value between -1 and 1
        const val = Math.sin(seed + i) / 2 + 0.5;
        return val * 2 - 1; // Scale to range [-1, 1]
      });
    });
  };
}

/**
 * Set up a ChromaDB collection with test data
 * @param client ChromaDB client
 * @param collectionName Collection name
 * @param documents Test documents to add
 * @returns The collection with data added
 */
export async function setupCollectionWithData(
  client: ChromaClient,
  collectionName: string,
  documents: TestDocument[]
): Promise<Collection> {
  const collection = await createTestCollection(client, collectionName);

  if (documents.length === 0) return collection;

  // Extract the data from the test documents
  const ids = documents.map(doc => doc.id);
  const texts = documents.map(doc => doc.text);
  const metadatas = documents.map(doc => doc.metadata);

  // Handle embeddings - either use provided ones or create random ones
  const embeddings = documents.map(doc => doc.embedding || createRandomEmbedding());

  // Add the documents to the collection
  await collection.add({
    ids,
    documents: texts,
    metadatas,
    embeddings
  });

  return collection;
}

/**
 * Validate ChromaDB query results
 * @param result Query result to validate
 * @param expectedResultCount Expected number of results
 * @param includeEmbeddings Whether embeddings should be included
 * @param includeDocuments Whether documents should be included
 * @param includeMetadatas Whether metadata should be included
 * @returns Validation result
 */
export function validateQueryResult(
  result: any,
  expectedResultCount: number,
  includeEmbeddings: boolean = false,
  includeDocuments: boolean = false,
  includeMetadatas: boolean = false
): { valid: boolean, errors: string[] } {
  const errors: string[] = [];

  // Check basic structure
  if (!result || !Array.isArray(result.ids)) {
    errors.push('Result is missing or has invalid structure');
    return { valid: false, errors };
  }

  // Check result count
  const actualCount = result.ids.length;
  if (actualCount !== expectedResultCount) {
    errors.push(`Expected ${expectedResultCount} results, got ${actualCount}`);
  }

  // Check embeddings
  if (includeEmbeddings) {
    if (!result.embeddings || !Array.isArray(result.embeddings)) {
      errors.push('Embeddings are missing or not an array');
    } else if (result.embeddings.length !== actualCount) {
      errors.push(`Expected ${actualCount} embeddings, got ${result.embeddings.length}`);
    } else {
      // Validate each embedding is an array of numbers
      for (let i = 0; i < result.embeddings.length; i++) {
        if (!Array.isArray(result.embeddings[i])) {
          errors.push(`Embedding at index ${i} is not an array`);
        } else if (!result.embeddings[i].every((val: any) => typeof val === 'number')) {
          errors.push(`Embedding at index ${i} contains non-numeric values`);
        }
      }
    }
  }

  // Check documents
  if (includeDocuments) {
    if (!result.documents || !Array.isArray(result.documents)) {
      errors.push('Documents are missing or not an array');
    } else if (result.documents.length !== actualCount) {
      errors.push(`Expected ${actualCount} documents, got ${result.documents.length}`);
    } else {
      // Validate each document is a string
      for (let i = 0; i < result.documents.length; i++) {
        if (typeof result.documents[i] !== 'string') {
          errors.push(`Document at index ${i} is not a string`);
        }
      }
    }
  }

  // Check metadatas
  if (includeMetadatas) {
    if (!result.metadatas || !Array.isArray(result.metadatas)) {
      errors.push('Metadatas are missing or not an array');
    } else if (result.metadatas.length !== actualCount) {
      errors.push(`Expected ${actualCount} metadatas, got ${result.metadatas.length}`);
    } else {
      // Validate each metadata is an object
      for (let i = 0; i < result.metadatas.length; i++) {
        if (!result.metadatas[i] || typeof result.metadatas[i] !== 'object') {
          errors.push(`Metadata at index ${i} is not an object`);
        }
      }
    }
  }

  return { 
    valid: errors.length === 0,
    errors
  };
}

