 */
function prepareDocumentsForChroma(docs: any[]) {
  const mockEmbedFn = createMockEmbeddingFunction(DEFAULT_EMBEDDING_DIM);

  const ids = docs.map(d => d.id);
  const documents = docs.map(d => `${d.title}\n\n${d.content}`);
  const metadatas = docs.map(d => ({
    title: d.title,
    tags: d.tags
  }));

  // Generate embeddings based on document content
  const embeddings = mockEmbedFn(documents);

  return { ids, documents, metadatas, embeddings };
}

/**
 * Mock search function to use in the application
 */
async function searchDocuments(
  collection: Collection,
  query: string,
  embeddingFn: any,
  filters: Record<string, any> = {},
  limit: number = 5
) {
  // Generate embedding for the query
  const queryEmbedding = embeddingFn([query])[0];

  // Build where clause from filters
  const whereClause = Object.keys(filters).length > 0 ? filters : undefined;

  // Perform similarity search
  return collection.query({
    queryEmbeddings: [queryEmbedding],
    nResults: limit,
    where: whereClause,
    include: [IncludeEnum.Documents, IncludeEnum.Metadatas, IncludeEnum.Distances]
  });
}

