      // Store this as our "snapshot"
      const snapshot = {
        id: result.ids[0],
        document: result.documents?.[0],
        metadata: result.metadatas?.[0],
        embeddingDimension: result.embeddings?.[0].length
      };

      // Compare with expected format
      const expectedSnapshot = {
        id: docId,
        document: docContent,
        metadata: metadata,
        embeddingDimension: DEFAULT_EMBEDDING_DIM
      };

      // Verify snapshot matches
      expect(snapshot.id).to.equal(expectedSnapshot.id);
      expect(snapshot.document).to.equal(expectedSnapshot.document);
      expect(snapshot.metadata).to.deep.equal(expectedSnapshot.metadata);
      expect(snapshot.embeddingDimension).to.equal(expectedSnapshot.embeddingDimension);

      // Clean up
      await collection.delete({ ids: [docId] });
    });
  });
});

