/**
 * ChromaDB Repository Implementation
 * 
 * This file demonstrates how to implement the repository pattern for ChromaDB
 * integration with Next.js using TypeScript. The repository pattern provides a
 * clean abstraction layer for working with ChromaDB in your application.
 */

import { ChromaClient, Collection, IncludeEnum } from 'chromadb';
import { z } from 'zod'; // For runtime type validation

// Define document schema
const DocumentSchema = z.object({
  id: z.string(),
  title: z.string(),
  content: z.string(),
  tags: z.array(z.string()).default([]),
  metadata: z.record(z.any()).optional(),
  createdAt: z.string().optional(),
  updatedAt: z.string().optional()
});

// Document type for TypeScript
export type Document = z.infer<typeof DocumentSchema>;

// Search result type
export type SearchResult = {
  id: string;
  document: Document;
  score: number;
};

// Repository interface
export interface DocumentRepository {
  initialize(): Promise<void>;
  addDocument(document: Document, embedding?: number[]): Promise<Document>;
  getDocumentById(id: string): Promise<Document | null>;
  searchDocuments(query: string, filters?: any, limit?: number): Promise<SearchResult[]>;
  updateDocument(id: string, updates: Partial<Document>, embedding?: number[]): Promise<Document>;
  deleteDocument(id: string): Promise<boolean>;
  listDocuments(filter?: any, limit?: number): Promise<Document[]>;
}

/**
 * ChromaDB implementation of the document repository
 */
export class ChromaDocumentRepository implements DocumentRepository {
  private client: ChromaClient;
  private collection: Collection | null = null;
  private collectionName: string;
  private embeddingFunction: (texts: string[]) => number[][];
  private initialized: boolean = false;

  constructor(
    embeddingFunction: (texts: string[]) => number[][],
    collectionName: string = 'documents',
    chromaUrl: string = 'http://localhost:8000'
  ) {
    this.client = new ChromaClient({ path: chromaUrl });
    this.collectionName = collectionName;
    this.embeddingFunction = embeddingFunction;
  }

  /**
   * Initialize the repository and create the collection if it doesn't exist
   */
  async initialize(): Promise<void> {
    if (this.initialized) return;

    try {
      // Get existing collection or create a new one
      const collections = await this.client.listCollections();
      const existingCollection = collections.find(c => c.name === this.collectionName);

      if (existingCollection) {
        this.collection = await this.client.getCollection({
          name: this.collectionName
        });
      } else {
        this.collection = await this.client.createCollection({
          name: this.collectionName,
          metadata: {
            description: 'Document collection for application',
            createdAt: new Date().toISOString()
          }
        });
      }

      this.initialized = true;
    } catch (error) {
      console.error('Failed to initialize ChromaDB repository:', error);
      throw new Error('ChromaDB repository initialization failed');
    }
  }

  /**
   * Add a document to the collection
   */
  async addDocument(document: Document, embedding?: number[]): Promise<Document> {
    if (!this.collection) await this.initialize();
    if (!this.collection) throw new Error('Collection not initialized');

    try {
      // Validate document
      const validatedDoc = DocumentSchema.parse({
        ...document,
        createdAt: document.createdAt || new Date().toISOString(),
        updatedAt: document.updatedAt || new Date().toISOString()
      });

      // Generate embedding if not provided
      const docText = `${validatedDoc.title}\n\n${validatedDoc.content}`;
      const docEmbedding = embedding || this.embeddingFunction([docText])[0];

      // Prepare metadata
      const metadata = {
        title: validatedDoc.title,
        tags: validatedDoc.tags,
        createdAt: validatedDoc.createdAt,
        updatedAt: validatedDoc.updatedAt,
        ...(validatedDoc.metadata || {})
      };

      // Add to ChromaDB
      await this.collection.add({
        ids: [validatedDoc.id],
        embeddings: [docEmbedding],
        metadatas: [metadata],
        documents: [docText]
      });

      return validatedDoc;
    } catch (error) {
      console.error('Failed to add document:', error);
      throw new Error('Failed to add document to ChromaDB');
    }
  }

  /**
   * Get a document by ID
   */
  async getDocumentById(id: string): Promise<Document | null> {
    if (!this.collection) await this.initialize();
    if (!this.collection) throw new Error('Collection not initialized');

    try {
      const result = await this.collection.get({
        ids: [id],
        include: [IncludeEnum.Documents, IncludeEnum.Metadatas]
      });

      if (result.ids.length === 0) {
        return null;
      }

      // Extract document
      const docText = result.documents?.[0] || '';
      const metadata = result.metadatas?.[0] || {};

      // Split document text into title and content
      const [title, ...contentParts] = docText.split('\n\n');
      const content = contentParts.join('\n\n');

      // Reconstruct document
      return {
        id,
        title: metadata.title || title,
        content,
        tags: metadata.tags || [],
        metadata: metadata,
        createdAt: metadata.createdAt,
        updatedAt: metadata.updatedAt
      };
    } catch (error) {
      console.error('Failed to get document:', error);
      throw new Error('Failed to retrieve document from ChromaDB');
    }
  }

  /**
   * Search for documents
   */
  async searchDocuments(
    query: string,
    filters: any = {},
    limit: number = 10
  ): Promise<SearchResult[]> {
    if (!this.collection) await this.initialize();
    if (!this.collection) throw new Error('Collection not initialized');

    try {
      // Generate embedding for the query
      const queryEmbedding = this.embeddingFunction([query])[0];

      // Build where clause from filters
      const whereClause = Object.keys(filters).length > 0 ? filters : undefined;

      // Perform similarity search
      const results = await this.collection.query({
        queryEmbeddings: [queryEmbedding],
        nResults: limit,
        where: whereClause,
        include: [IncludeEnum.Documents, IncludeEnum.Metadatas, IncludeEnum.Distances]
      });

      // Format results
      if (!results.ids[0] || results.ids[0].length === 0) {
        return [];
      }

      return results.ids[0].map((id, idx) => {
        const docText = results.documents?.[0][idx] || '';
        const metadata = results.metadatas?.[0][idx] || {};
        const distance = results.distances?.[0][idx] || 1;

        // Split document text into title and content
        const [title, ...contentParts] = docText.split('\n\n');
        const content = contentParts.join('\n\n');

        // Calculate score (1 - distance) for similarity score between 0-1
        const score = 1 - Math.min(distance, 1);

        return {
          id,
          document: {
            id,
            title: metadata.title || title,
            content,
            tags: metadata.tags || [],
            metadata,
            createdAt: metadata.createdAt,
            updatedAt: metadata.updatedAt
          },
          score
        };
      });
    } catch (error) {
      console.error('Failed to search documents:', error);
      throw new Error('Failed to search documents in ChromaDB');
    }
  }

  /**
   * Update a document
   */
  async updateDocument(
    id: string,
    updates: Partial<Document>,
    embedding?: number[]
  ): Promise<Document> {
    if (!this.collection) await this.initialize();
    if (!this.collection) throw new Error('Collection not initialized');

    try {
      // Get existing document
      const existingDoc = await this.getDocumentById(id);

      if (!existingDoc) {
        throw new Error(`Document with ID ${id} not found`);
      }

      // Merge updates with existing document
      const updatedDoc: Document = {
        ...existingDoc,
        ...updates,
        updatedAt: new Date().toISOString()
      };

      // Generate new embedding if needed
      const docText = `${updatedDoc.title}\n\n${updatedDoc.content}`;
      const docEmbedding = embedding || this.embeddingFunction([docText])[0];

      // Prepare metadata
      const metadata = {
        title: updatedDoc.title,
        tags: updatedDoc.tags,
        createdAt: updatedDoc.createdAt,
        updatedAt: updatedDoc.updatedAt,
        ...(updatedDoc.metadata || {})
      };

      // Update in ChromaDB
      await this.collection.update({
        ids: [id],
        embeddings: [docEmbedding],
        metadatas: [metadata],
        documents: [docText]
      });

      return updatedDoc;
    } catch (error) {
      console.error('Failed to update document:', error);
      throw new Error('Failed to update document in ChromaDB');
    }
  }

  /**
   * Delete a document
   */
  async deleteDocument(id: string): Promise<boolean> {
    if (!this.collection) await this.initialize();
    if (!this.collection) throw new Error('Collection not initialized');

    try {
      // Check if document exists
      const existingDoc = await this.getDocumentById(id);

      if (!existingDoc) {
        return false;
      }

      // Delete from ChromaDB
      await this.collection.delete({
        ids: [id]
      });

      return true;
    } catch (error) {
      console.error('Failed to delete document:', error);
      throw new Error('Failed to delete document from ChromaDB');
    }
  }

  /**
   * List documents with optional filter
   */
  async listDocuments(filter: any = {}, limit: number = 100): Promise<Document[]> {
    if (!this.collection) await this.initialize();
    if (!this.collection) throw new Error('Collection not initialized');

    try {
      // Build where clause from filter
      const whereClause = Object.keys(filter).length > 0 ? filter : undefined;

      // Query documents
      const result = await this.collection.get({
        where: whereClause,
        limit,
        include: [IncludeEnum.Documents, IncludeEnum.Metadatas]
      });

      if (result.ids.length === 0) {
        return [];
      }

      // Format results
      return result.ids.map((id, idx) => {
        const docText = result.documents?.[idx] || '';
        const metadata = result.metadatas?.[idx] || {};

        // Split document text into title and content
        const [title, ...contentParts] = docText.split('\n\n');
        const content = contentParts.join('\n\n');

        return {
          id,
          title: metadata.title || title,
          content,
          tags: metadata.tags || [],
          metadata,
          createdAt: metadata.createdAt,
          updatedAt: metadata.updatedAt
        };
      });
    } catch (error) {
      console.error('Failed to list documents:', error);
      throw new Error('Failed to list documents from ChromaDB');
    }
  }
}

/**
 * Helper to create a ChromaDB document repository singleton
 */
let repositoryInstance: ChromaDocumentRepository | null = null;

export function getDocumentRepository(
  embeddingFunction: (texts: string[]) => number[][],
  collectionName: string = 'documents',
  chromaUrl: string = process.env.CHROMA_URL || 'http://localhost:8000'
): ChromaDocumentRepository {
  if (!repositoryInstance) {
    repositoryInstance = new ChromaDocumentRepository(
      embeddingFunction,
      collectionName,
      chromaUrl
    );
  }

  return repositoryInstance;
}

