# ChromaDB Testing Guide for Next.js/TypeScript Environment

This guide provides practical test implementations for ChromaDB collection operations in a Next.js/TypeScript environment, focusing on collection creation and metadata retrieval with ChromaDB 1.5.0.

## Table of Contents

1. [Setup and Environment Configuration](#setup-and-environment-configuration)
2. [Test Utilities](#test-utilities)
3. [Collection Creation Tests](#collection-creation-tests)
4. [Collection Metadata Tests](#collection-metadata-tests)
5. [Test Cleanup and Best Practices](#test-cleanup-and-best-practices)

## Setup and Environment Configuration

First, let's set up the necessary files and configurations for testing ChromaDB in a Next.js/TypeScript environment.

### File Structure

```
/project-root
  /src
    /lib
      /chromadb
        /client.ts        # ChromaDB client implementation
        /types.ts         # TypeScript interfaces
    /tests
      /lib
        /chromadb
          /client.test.ts # Main test file
          /test-utils.ts  # Test utilities
  /jest.config.js         # Jest configuration
```

### jest.config.js

```javascript
module.exports = {
  preset: 'ts-jest',
  testEnvironment: 'node',
  moduleNameMapper: {
    '^@/(.*)$': '<rootDir>/src/$1',
  },
  setupFilesAfterEnv: ['<rootDir>/src/tests/setupTests.ts'],
  testMatch: ['**/?(*.)+(spec|test).[jt]s?(x)'],
};
```

### src/tests/setupTests.ts

```typescript
// Global test setup
jest.setTimeout(20000); // Increase timeout for ChromaDB operations

// Mock environment variables
process.env.CHROMADB_HOST = 'localhost';
process.env.CHROMADB_PORT = '8000';
```

## Core Types and Interfaces

Let's define the TypeScript interfaces that we'll use throughout our tests.

### src/lib/chromadb/types.ts

```typescript
// ChromaDB client types
export interface ChromaDBClientConfig {
  path?: string;
  host?: string;
  port?: string;
  ssl?: boolean;
  headers?: Record<string, string>;
}

export interface CollectionMetadata {
  name: string;
  [key: string]: any;
}

export interface EmbeddingFunction {
  generate: (texts: string[]) => Promise<number[][]>;
}

export interface CreateCollectionOptions {
  name: string;
  metadata?: CollectionMetadata;
  embeddingFunction?: EmbeddingFunction;
}

export interface CollectionInfo {
  name: string;
  id: string;
  metadata: CollectionMetadata;
  tenant: string;
  database: string;
}

// Test specific types
export interface TestContext {
  client: any; // ChromaClient
  collectionsToCleanup: string[];
}
```

## Test Utilities

Now, let's create test utilities to help with setup, teardown, and other common operations.

### src/tests/lib/chromadb/test-utils.ts

```typescript
import { ChromaClient } from 'chromadb';
import { TestContext, CollectionMetadata, EmbeddingFunction } from '@/lib/chromadb/types';

/**
 * Creates a ChromaDB client for testing
 */
export function createTestClient(): ChromaClient {
  return new ChromaClient({
    host: process.env.CHROMADB_HOST || 'localhost',
    port: process.env.CHROMADB_PORT || '8000',
  });
}

/**
 * Initializes a test context with ChromaDB client
 */
export async function initializeTestContext(): Promise<TestContext> {
  const client = createTestClient();

  // Wait for connection to ensure ChromaDB is ready
  await client.heartbeat();

  return {
    client,
    collectionsToCleanup: [],
  };
}

/**
 * Cleans up collections created during tests
 */
export async function cleanupTestContext(context: TestContext): Promise<void> {
  const { client, collectionsToCleanup } = context;

  // Delete all collections that were created during testing
  for (const collectionName of collectionsToCleanup) {
    try {
      await client.deleteCollection({ name: collectionName });
    } catch (error) {
      console.warn(`Failed to delete collection ${collectionName}:`, error);
    }
  }
}

/**
 * Generates a unique collection name to avoid conflicts in tests
 */
export function generateUniqueCollectionName(prefix: string = 'test'): string {
  const timestamp = Date.now();
  const randomSuffix = Math.floor(Math.random() * 1000);
  return `${prefix}_${timestamp}_${randomSuffix}`;
}

/**
 * Creates a simple embedding function for testing
 */
export function createMockEmbeddingFunction(): EmbeddingFunction {
  return {
    generate: async (texts: string[]): Promise<number[][]> => {
      // Simple mock that creates fixed-length embeddings
      return texts.map(text => {
        // Create a deterministic embedding based on the text content
        const embedding = new Array(10).fill(0);
        for (let i = 0; i < Math.min(text.length, 10); i++) {
          embedding[i] = text.charCodeAt(i) / 255; // Normalize to 0-1
        }
        return embedding;
      });
    }
  };
}

/**
 * Creates sample collection metadata for testing
 */
export function createSampleMetadata(): CollectionMetadata {
  return {
    name: 'test-collection',
    description: 'A collection created for testing purposes',
    created_at: new Date().toISOString(),
    test_field: true,
    version: '1.0.0',
  };
}

/**
 * Asserts that a collection exists
 */
export async function assertCollectionExists(
  client: ChromaClient, 
  collectionName: string
): Promise<void> {
  const collections = await client.listCollections();
  const exists = collections.some(collection => collection.name === collectionName);
  expect(exists).toBe(true);
}
```

## Collection Creation Tests

Now, let's implement tests for collection creation with various configurations.

### src/tests/lib/chromadb/client.test.ts (Part 1: Collection Creation)

```typescript
import { ChromaClient } from 'chromadb';
import { 
  initializeTestContext, 
  cleanupTestContext, 
  generateUniqueCollectionName,
  createSampleMetadata,
  createMockEmbeddingFunction,
  assertCollectionExists,
} from './test-utils';
import { TestContext } from '@/lib/chromadb/types';

describe('ChromaDB Collection Operations', () => {
  let testContext: TestContext;

  beforeAll(async () => {
    testContext = await initializeTestContext();
  });

  afterAll(async () => {
    await cleanupTestContext(testContext);
  });

  describe('Collection Creation', () => {
    test('should create a basic collection', async () => {
      // Arrange
      const collectionName = generateUniqueCollectionName();
      testContext.collectionsToCleanup.push(collectionName);

      // Act
      const collection = await testContext.client.createCollection({
        name: collectionName,
      });

      // Assert
      expect(collection).toBeDefined();
      expect(collection.name).toBe(collectionName);
      await assertCollectionExists(testContext.client, collectionName);
    });

    test('should create a collection with metadata', async () => {
      // Arrange
      const collectionName = generateUniqueCollectionName();
      testContext.collectionsToCleanup.push(collectionName);
      const metadata = createSampleMetadata();

      // Act
      const collection = await testContext.client.createCollection({
        name: collectionName,
        metadata,
      });

      // Assert
      expect(collection).toBeDefined();
      expect(collection.name).toBe(collectionName);

      const collectionInfo = await collection.getMetadata();
      expect(collectionInfo).toMatchObject(metadata);
    });

    test('should create a collection with custom embedding function', async () => {
      // Arrange
      const collectionName = generateUniqueCollectionName();
      testContext.collectionsToCleanup.push(collectionName);
      const embeddingFunction = createMockEmbeddingFunction();

      // Act
      const collection = await testContext.client.createCollection({
        name: collectionName,
        embeddingFunction,
      });

      // Assert
      expect(collection).toBeDefined();

      // Test the embedding function by adding a document
      const documents = ["This is a test document"];
      const ids = ["test-id-1"];

      await collection.add({
        ids,
        documents,
      });

      // Retrieve and verify
      const result = await collection.get({
        ids,
      });

      expect(result).toBeDefined();
      expect(result.ids).toEqual(ids);
      expect(result.documents).toEqual(documents);
    });

    test('should throw error when creating collection with duplicate name', async () => {
      // Arrange
      const collectionName = generateUniqueCollectionName();
      testContext.collectionsToCleanup.push(collectionName);

      // Create first collection
      await testContext.client.createCollection({
        name: collectionName,
      });

      // Act & Assert: Creating again should throw
      await expect(
        testContext.client.createCollection({
          name: collectionName,
        })
      ).rejects.toThrow();
    });

    test('should create collection with get_or_create if collection exists', async () => {
      // Arrange
      const collectionName = generateUniqueCollectionName();
      testContext.collectionsToCleanup.push(collectionName);

      // Create first collection
      const collection1 = await testContext.client.createCollection({
        name: collectionName,
      });

      // Act: Get or create should return existing collection
      const collection2 = await testContext.client.getOrCreateCollection({
        name: collectionName,
      });

      // Assert
      expect(collection2).toBeDefined();
      expect(collection2.name).toBe(collectionName);

      // Only one collection should exist with this name
      const collections = await testContext.client.listCollections();
      const matchingCollections = collections.filter(c => c.name === collectionName);
      expect(matchingCollections.length).toBe(1);
    });
  });
});
```

## Collection Metadata Tests

Let's continue with tests focused on retrieving and validating collection metadata.

### src/tests/lib/chromadb/client.test.ts (Part 2: Collection Metadata)

```typescript
// Continuing from the previous test file...

describe('Collection Metadata Operations', () => {
  test('should retrieve collection info', async () => {
    // Arrange
    const collectionName = generateUniqueCollectionName();
