      ids,
      documents,
    });

    // Verify documents were added
    let count = await collection.count();
    expect(count).toBe(2);

    // Act: Reset the collection
    await collection.delete();

    // Assert: Collection should be empty
    count = await collection.count();
    expect(count).toBe(0);

    // Collection should still exist
    await assertCollectionExists(testContext.client, collectionName);
  });

  test('should handle parallel collection operations correctly', async () => {
    // Arrange: Define multiple collections to create simultaneously
    const collectionPromises = [];
    const collectionNames = [];

    for (let i = 0; i < 5; i++) {
      const name = generateUniqueCollectionName(`parallel-${i}`);
      collectionNames.push(name);
      testContext.collectionsToCleanup.push(name);

      collectionPromises.push(
        testContext.client.createCollection({
          name,
          metadata: { parallel_index: i }
        })
      );
    }

    // Act: Create collections in parallel
    await Promise.all(collectionPromises);

    // Assert: All collections should exist
    const collections = await testContext.client.listCollections();

    for (const name of collectionNames) {
      const exists = collections.some(collection => collection.name === name);
      expect(exists).toBe(true);
    }
  });
});

