## Common Test Utilities

Create a `testUtils.ts` file with common utilities for testing:

```typescript
// __tests__/db/utils/testUtils.ts
import { ChromaClient, Collection, GetEmbeddingFunction, Metadata } from 'chromadb';

/**
 * Creates a test ChromaDB client
 */
export const createTestClient = (): ChromaClient => {
  return new ChromaClient({
    path: process.env.CHROMA_TEST_API_URL || 'http://localhost:8000',
  });
};

/**
 * Creates a test collection with optional documents
 */
export const createTestCollection = async (
  client: ChromaClient,
  collectionName: string,
  metadata?: Metadata,
  embeddings?: number[][],
  documents?: string[],
  ids?: string[]
): Promise<Collection> => {
  const collection = await client.createCollection({
    name: collectionName,
    metadata: metadata || { test: true },
  });

  // Add documents if provided
  if (documents && documents.length > 0) {
    const embeddingFunction: GetEmbeddingFunction = 
      embeddings ? () => Promise.resolve(embeddings) : await client.getEmbeddingFunction();

    await collection.add({
      ids: ids || documents.map((_, i) => `test_id_${i}`),
      documents,
      embeddings: embeddings || await embeddingFunction(documents),
    });
  }

  return collection;
};

/**
 * Generates a unique collection name for testing
 */
export const generateTestCollectionName = (prefix = 'test'): string => {
  return `${prefix}_${Date.now()}_${Math.floor(Math.random() * 1000)}`;
};

/**
 * Cleans up a test collection
 */
export const cleanupTestCollection = async (
  client: ChromaClient,
  collectionName: string
): Promise<void> => {
  try {
    await client.deleteCollection({ name: collectionName });
  } catch (error) {
    // Ignore errors if collection doesn't exist
    console.warn(`Error cleaning up collection ${collectionName}:`, error);
  }
};

/**
 * Creates multiple test collections for testing list operations
 */
export const createMultipleTestCollections = async (
  client: ChromaClient,
  count: number,
  namePrefix = 'test',
  metadataGenerator?: (index: number) => Metadata
): Promise<string[]> => {
  const collectionNames: string[] = [];

  for (let i = 0; i < count; i++) {
    const name = generateTestCollectionName(namePrefix);
    const metadata = metadataGenerator ? metadataGenerator(i) : { testIndex: i };

    await client.createCollection({
      name,
      metadata,
    });

    collectionNames.push(name);
  }

  return collectionNames;
};
```

