// __tests__/db/collection/updateCollection.test.ts
import { ChromaClient, Collection } from 'chromadb';
import { 
  createTestClient, 
  generateTestCollectionName, 
  cleanupTestCollection 
} from '../utils/testUtils';

describe('Update Collection Tests', () => {
  let client: ChromaClient;
  let collectionName: string;
  let collection: Collection;

  beforeEach(async () => {
    client = createTestClient();
    collectionName = generateTestCollectionName();

    // Create a fresh collection for each test
    collection = await client.createCollection({
      name: collectionName,
      metadata: { 
        description: 'Initial description',
        version: 1,
        tags: ['initial', 'test']
      }
    });
  });

  afterEach(async () => {
    await cleanupTestCollection(client, collectionName);
  });

  test('should update collection metadata', async () => {
    // Update the collection metadata
    const updatedMetadata = { 
      description: 'Updated description',
      version: 2,
      tags: ['updated', 'test']
    };

    await collection.modify({ metadata: updatedMetadata });

    // Get the collection to verify updates
    const retrievedCollection = await client.getCollection({
      name: collectionName
    });

    // Check if metadata was updated correctly
    expect(retrievedCollection.metadata).toEqual(updatedMetadata);
  });

  test('should partially update collection metadata', async () => {
    // Only update specific fields
    await collection.modify({
      metadata: {
        description: 'Partially updated description',
        // Omit other fields to test partial update
      }
    });

    // Get the collection to verify updates
    const retrievedCollection = await client.getCollection({
      name: collectionName
    });

    // Check if metadata was partially updated
    expect(retrievedCollection.metadata.description).toBe('Partially updated description');
    expect(retrievedCollection.metadata.version).toBe(1); // Should remain unchanged
    expect(retrievedCollection.metadata.tags).toEqual(['initial', 'test']); // Should remain unchanged
  });

  test('should update collection name', async () => {
    // Create a new name for the collection
    const newCollectionName = generateTestCollectionName('renamed');

    try {
      // Update the collection name
      await collection.modify({ name: newCollectionName });

      // Get the collection with the new name to verify it exists
      const retrievedCollection = await client.getCollection({
        name: newCollectionName
      });

      // Check if the new collection exists with the same metadata
      expect(retrievedCollection.name).toBe(newCollectionName);
      expect(retrievedCollection.metadata).toEqual(collection.metadata);

      // Check if the old collection name no longer exists
      await expect(
        client.getCollection({ name: collectionName })
      ).rejects.toThrow();

    } finally {
      // Clean up the renamed collection
      await cleanupTestCollection(client, newCollectionName);
    }
  });

  test('should handle updating a collection with documents', async () => {
    // Add documents to the collection
    const ids = ['doc1', 'doc2', 'doc3'];
    const documents = ['First document', 'Second document', 'Third document'];

    await collection.add({
      ids,
      documents,
    });

    // Update collection metadata
    const updatedMetadata = { 
      description: 'Collection with documents',
      documentCount: 3
    };

    await collection.modify({ metadata: updatedMetadata });

    // Get the collection to verify updates
    const retrievedCollection = await client.getCollection({
      name: collectionName
    });

    // Check if metadata was updated
    expect(retrievedCollection.metadata).toEqual(updatedMetadata);

    // Verify documents still exist
    const count = await retrievedCollection.count();
    expect(count).toBe(3);
  });

  test('should fail when updating a non-existent collection', async () => {
    // Create a non-existent collection object
    const nonExistentCollectionName = 'non_existent_collection';
    let nonExistentCollection: Collection;

    try {
      // Try to get a non-existent collection
      nonExistentCollection = await client.getCollection({
        name: nonExistentCollectionName
      });
    } catch (error) {
      // Create a collection object with the non-existent name
      nonExistentCollection = await client.createCollection({
        name: nonExistentCollectionName
      });

      // Immediately delete it to simulate a non-existent collection
      await client.deleteCollection({ name: nonExistentCollectionName });
    }

    // Try to update the non-existent collection
    await expect(
      nonExistentCollection.modify({ metadata: { test: true } })
    ).rejects.toThrow();
  });
});
