    await client.deleteCollection({ name: collectionName });

    // Verify the collection is deleted
    const collectionsAfterDelete = await client.listCollections();
    expect(collectionsAfterDelete.map(c => c.name)).not.toContain(collectionName);
  });

  test('should delete a collection with documents', async () => {
    // Create a test collection with documents
    const collectionName = generateTestCollectionName();
    const documents = ['Document 1', 'Document 2', 'Document 3'];
    const ids = ['id1', 'id2', 'id3'];

    await createTestCollection(client, collectionName, { test: true }, undefined, documents, ids);

    // Verify the collection exists and has documents
    const collection = await client.getCollection({ name: collectionName });
    const count = await collection.count();
    expect(count).toBe(3);

    // Delete the collection
    await client.deleteCollection({ name: collectionName });

    // Verify the collection is deleted
    const collectionsAfterDelete = await client.listCollections();
    expect(collectionsAfterDelete.map(c => c.name)).not.toContain(collectionName);
  });

  test('should handle deleting a non-existent collection', async () => {
    const nonExistentCollectionName = 'non_existent_collection';

    // Try to delete a non-existent collection
    // This should not throw an error in newer versions of ChromaDB (1.5.0+)
    await client.deleteCollection({ name: nonExistentCollectionName });

    // Verify the operation didn't affect other collections
    const collectionsBeforeDelete = await client.listCollections();
    await client.deleteCollection({ name: nonExistentCollectionName });
    const collectionsAfterDelete = await client.listCollections();

    expect(collectionsAfterDelete.length).toBe(collectionsBeforeDelete.length);
  });

  test('should remove collection data from storage', async () => {
    // Create a test collection with documents
    const collectionName = generateTestCollectionName();
    const documents = ['Persistent data test'];
    const ids = ['persist1'];

    await createTestCollection(client, collectionName, { test: true }, undefined, documents, ids);

    // Delete the collection
    await client.deleteCollection({ name: collectionName });

    // Try to recreate the collection with the same name
    const newCollection = await client.createCollection({
      name: collectionName,
      metadata: { recreated: true }
    });

    // Verify it's a fresh collection with no documents
    const count = await newCollection.count();
    expect(count).toBe(0);
    expect(newCollection.metadata).toEqual({ recreated: true });

    // Clean up
    await client.deleteCollection({ name: collectionName });
  });

  test('should handle concurrent deletion requests for the same collection', async () => {
    // Create a test collection
    const collectionName = generateTestCollectionName();
    await createTestCollection(client, collectionName);

    // Attempt to delete the collection multiple times concurrently
    const deletionPromises = Array(3).fill(0).map(() => 
      client.deleteCollection({ name: collectionName })
    );

    // All promises should resolve without errors
    await expect(Promise.all(deletionPromises)).resolves.not.toThrow();

    // Verify the collection is deleted
    const collectionsAfterDelete = await client.listCollections();
    expect(collectionsAfterDelete.map(c => c.name)).not.toContain(collectionName);
  });
});
