      c => c.metadata && c.metadata.category === 'even'
    );

    // Should have approximately half of the test collections
    expect(evenCollections.length).toBe(Math.ceil(testCollectionNames.length / 2));

    // All should have the 'even' category
    evenCollections.forEach(c => {
      expect(c.metadata.category).toBe('even');
    });
  });

  test('should sort collections by creation time', async () => {
    const collections = await client.listCollections();

    // Filter only our test collections
    const testCollections = collections.filter(c => 
      testCollectionNames.includes(c.name)
    );

    // Sort by createdAt in metadata
    const sortedCollections = [...testCollections].sort((a, b) => {
      const timeA = new Date(a.metadata.createdAt).getTime();
      const timeB = new Date(b.metadata.createdAt).getTime();
      return timeA - timeB;
