      expect(page1.map(c => c.id)).not.toEqual(page2.map(c => c.id));

      // Verify we can get all pages
      const manuallyCollectedCollections = [];
      for (let i = 0; i < Math.ceil(allCollections.length / pageSize); i++) {
        const page = allCollections.slice(i * pageSize, (i + 1) * pageSize);
        manuallyCollectedCollections.push(...page);
      }

      expect(manuallyCollectedCollections.length).toBe(allCollections.length);

    } finally {
