      expect(c.metadata.priority).toBeGreaterThan(2);
    });

    // Check if we have the expected number of collections
    // (odd indices 3, 5, 7, 9... that are also > 2)
    const expectedCount = testCollectionNames
      .filter((_, i) => i % 2 !== 0 && (i + 1) > 2)
      .length;

    expect(filteredCollections.length).toBe(expectedCount);
  });
});
