## Shared Test Utilities

Create a file named `__tests__/utils/chroma-test-utils.ts`:

```typescript
import { ChromaClient, Collection } from 'chromadb';

// Define the interface for memory items
export interface MemoryItem {
  id: string;
  content: string;
  timestamp: string;
  category?: string;
  importance?: number;
  metadata?: Record<string, any>;
}

// Test data generator
export function generateTestItems(count: number = 5): MemoryItem[] {
  const items: MemoryItem[] = [];
  const baseTimestamp = new Date().toISOString();

  for (let i = 0; i < count; i++) {
    items.push({
      id: `test-item-${i}`,
      content: `This is test content for item ${i}`,
      timestamp: baseTimestamp,
      category: i % 2 === 0 ? 'category-a' : 'category-b',
      importance: (i % 3) + 1,
      metadata: {
        source: 'test',
        tags: [`tag-${i % 3}`],
        wordCount: 50 + (i * 10),
      }
    });
  }

  return items;
}

// Setup test collection
export async function setupTestCollection(
  client: ChromaClient,
  collectionName: string = 'test_collection'
): Promise<Collection> {
  try {
    await client.deleteCollection({ name: collectionName });
  } catch (e) {
    // Collection may not exist yet
  }

  return await client.createCollection({
    name: collectionName,
    metadata: { 'test': true }
  });
}

// Populate test collection with items
export async function populateCollection(
  collection: Collection,
  items: MemoryItem[]
): Promise<void> {
  const ids = items.map(item => item.id);
  const documents = items.map(item => item.content);
  const metadatas = items.map(item => ({
    timestamp: item.timestamp,
    category: item.category,
    importance: item.importance,
    ...item.metadata
  }));

  await collection.add({
    ids,
    documents,
    metadatas
  });
}

// Helper to clear a collection
export async function clearCollection(collection: Collection): Promise<void> {
  const allItems = await collection.get();
  if (allItems.ids.length > 0) {
    await collection.delete({ ids: allItems.ids });
  }
}
```

