  let testItems: MemoryItem[];

  beforeAll(async () => {
    // Initialize ChromaDB client
    client = new ChromaClient({
      path: process.env.CHROMA_URL || 'http://localhost:8000'
    });
  });

  beforeEach(async () => {
    // Setup a fresh test collection before each test
    collection = await setupTestCollection(client);

    // Generate and add test items
    testItems = generateTestItems(10);
    await populateCollection(collection, testItems);
  });

  afterEach(async () => {
    // Clean up after each test
    await clearCollection(collection);
  });

  afterAll(async () => {
    // Clean up after all tests
    try {
      await client.deleteCollection({ name: 'test_collection' });
    } catch (e) {
      // Ignore errors during cleanup
    }
  });

  // 1.1 Test retrieving entry by exact ID
  test('should retrieve an entry by exact ID', async () => {
    // Get a specific item by ID
    const targetId = testItems[3].id;
    const result = await collection.get({ ids: [targetId] });

    expect(result.ids).toHaveLength(1);
    expect(result.ids[0]).toBe(targetId);
    expect(result.documents[0]).toBe(testItems[3].content);

    // Verify metadata
    expect(result.metadatas[0].category).toBe(testItems[3].category);
    expect(result.metadatas[0].importance).toBe(testItems[3].importance);
  });

  // 1.2 Test retrieving multiple entries by ID
  test('should retrieve multiple entries by IDs', async () => {
    const targetIds = [testItems[1].id, testItems[4].id, testItems[7].id];
    const result = await collection.get({ ids: targetIds });

    expect(result.ids).toHaveLength(3);
    expect(result.ids).toEqual(expect.arrayContaining(targetIds));

    // Check all documents are retrieved
    targetIds.forEach(id => {
      const itemIndex = testItems.findIndex(item => item.id === id);
      const resultIndex = result.ids.indexOf(id);

      expect(resultIndex).not.toBe(-1);
      expect(result.documents[resultIndex]).toBe(testItems[itemIndex].content);
    });
  });

  // 1.3 Test querying entries by similarity search
  test('should find entries by similarity search', async () => {
    // Query for items similar to a specific item
    const queryText = "This is test content";
    const result = await collection.query({
      queryTexts: [queryText],
      nResults: 3
    });

    expect(result.ids[0]).toHaveLength(3);

    // Verify we got results (we can't predict exact matches due to embeddings)
    expect(result.documents[0].length).toBe(3);

    // Each result should contain our query text
    result.documents[0].forEach(doc => {
      expect(doc).toContain("test content");
    });
  });

  // 1.4 Test filtering entries by metadata
  test('should filter entries by metadata', async () => {
    // Filter by category
    const result = await collection.get({
      where: { category: "category-a" }
    });

    // Half of our items should be in category-a
    expect(result.ids.length).toBe(5);

    // Verify all results have the correct category
    result.metadatas.forEach(metadata => {
      expect(metadata.category).toBe("category-a");
    });
  });

  // 1.5 Test filtering with multiple metadata criteria
  test('should filter entries with multiple metadata criteria', async () => {
    // Filter by category and importance
    const result = await collection.get({
      where: { 
        category: "category-b",
        importance: 2
      }
    });

    // Verify results match both criteria
    result.metadatas.forEach(metadata => {
      expect(metadata.category).toBe("category-b");
      expect(metadata.importance).toBe(2);
    });
  });

  // 1.6 Test combining filtering and similarity search
  test('should combine filtering and similarity search', async () => {
    const queryText = "test content";
    const result = await collection.query({
      queryTexts: [queryText],
      where: { category: "category-a" },
      nResults: 2
    });

    expect(result.ids[0]).toHaveLength(2);

    // Check that all results have the correct category
    result.metadatas[0].forEach(metadata => {
      expect(metadata.category).toBe("category-a");
    });
  });

  // 1.7 Test error handling for queries with missing params
  test('should handle queries with missing parameters', async () => {
    // Query with empty array
    await expect(
      collection.query({
        queryTexts: [],
        nResults: 2
      })
    ).rejects.toThrow();

    // Query with null text
    await expect(
      collection.query({
        queryTexts: [null as any],
        nResults: 2
      })
    ).rejects.toThrow();
  });

  // 1.8 Test error handling for getting non-existent ID
  test('should handle getting non-existent ID', async () => {
    const result = await collection.get({ ids: ["non-existent-id"] });

    // Should return empty arrays
    expect(result.ids).toHaveLength(0);
    expect(result.documents).toHaveLength(0);
    expect(result.metadatas).toHaveLength(0);
  });

  // 1.9 Test pagination of results
  test('should paginate results correctly', async () => {
    // Get first page
    const page1 = await collection.get({
      limit: 3,
      offset: 0
    });

    // Get second page
    const page2 = await collection.get({
      limit: 3,
      offset: 3
    });

    // Get third page
    const page3 = await collection.get({
      limit: 3,
      offset: 6
    });

    // Check page sizes
    expect(page1.ids).toHaveLength(3);
    expect(page2.ids).toHaveLength(3);
    expect(page3.ids).toHaveLength(3);

    // Check that pages don't overlap
    const allIds = [...page1.ids, ...page2.ids, ...page3.ids];
    const uniqueIds = [...new Set(allIds)];
    expect(uniqueIds).toHaveLength(9);
  });
});
