## 2. Testing Update Operations

Create a file named `__tests__/chromadb-update.test.ts`:

```typescript
import { ChromaClient, Collection } from 'chromadb';
import { 
  MemoryItem, 
  setupTestCollection, 
  generateTestItems, 
  populateCollection,
  clearCollection
} from './utils/chroma-test-utils';

describe('ChromaDB Update Operations', () => {
  let client: ChromaClient;
  let collection: Collection;
  let testItems: MemoryItem[];

  beforeAll(async () => {
    // Initialize ChromaDB client
    client = new ChromaClient({
      path: process.env.CHROMA_URL || 'http://localhost:8000'
    });
  });

  beforeEach(async () => {
    // Setup a fresh test collection before each test
    collection = await setupTestCollection(client);

    // Generate and add test items
    testItems = generateTestItems(5);
    await populateCollection(collection, testItems);
  });

  afterEach(async () => {
    // Clean up after each test
    await clearCollection(collection);
  });

  afterAll(async () => {
    // Clean up after all tests
    try {
      await client.deleteCollection({ name: 'test_collection' });
    } catch (e) {
      // Ignore errors during cleanup
    }
  });

  // 2.1 Test updating entry content
  test('should update entry content', async () => {
    const targetId = testItems[2].id;
    const updatedContent = "This is updated content for testing";

    // Update the content
    await collection.update({
      ids: [targetId],
      documents: [updatedContent]
    });

    // Verify the update
    const result = await collection.get({ ids: [targetId] });

    expect(result.ids).toHaveLength(1);
    expect(result.documents[0]).toBe(updatedContent);

    // Metadata should remain unchanged
    expect(result.metadatas[0].category).toBe(testItems[2].category);
    expect(result.metadatas[0].importance).toBe(testItems[2].importance);
  });

  // 2.2 Test updating entry metadata
  test('should update entry metadata', async () => {
    const targetId = testItems[1].id;
    const updatedMetadata = {
      timestamp: testItems[1].timestamp,
      category: "updated-category",
      importance: 5,
      tags: ["updated", "test"]
    };

    // Update only the metadata
    await collection.update({
      ids: [targetId],
      metadatas: [updatedMetadata]
    });

    // Verify the update
    const result = await collection.get({ ids: [targetId] });

    expect(result.ids).toHaveLength(1);
    expect(result.documents[0]).toBe(testItems[1].content); // Content unchanged

    // Metadata should be updated
    expect(result.metadatas[0].category).toBe("updated-category");
    expect(result.metadatas[0].importance).toBe(5);
    expect(result.metadatas[0].tags).toContain("updated");
  });

  // 2.3 Test updating both content and metadata
  test('should update both content and metadata', async () => {
    const targetId = testItems[0].id;
    const updatedContent = "This is completely new content";
    const updatedMetadata = {
      timestamp: new Date().toISOString(),
      category: "new-category",
      importance: 10,
      source: "update-test"
    };

    // Update both content and metadata
    await collection.update({
      ids: [targetId],
      documents: [updatedContent],
      metadatas: [updatedMetadata]
    });

    // Verify the update
    const result = await collection.get({ ids: [targetId] });

    expect(result.ids).toHaveLength(1);
    expect(result.documents[0]).toBe(updatedContent);
    expect(result.metadatas[0].category).toBe("new-category");
    expect(result.metadatas[0].importance).toBe(10);
    expect(result.metadatas[0].source).toBe("update-test");
  });

  // 2.4 Test updating multiple entries at once
  test('should update multiple entries simultaneously', async () => {
    const targetIds = [testItems[1].id, testItems[3].id];
    const updatedContents = [
      "Updated content for item 1",
      "Updated content for item 3"
    ];
    const updatedMetadatas = [
      { ...testItems[1].metadata, importance: 8 },
      { ...testItems[3].metadata, importance: 9 }
    ];

    // Update multiple entries
    await collection.update({
      ids: targetIds,
      documents: updatedContents,
      metadatas: updatedMetadatas
    });

    // Verify the updates
    const result = await collection.get({ ids: targetIds });

    expect(result.ids).toHaveLength(2);

    // Find results by ID since order may vary
    targetIds.forEach((id, index) => {
      const resultIndex = result.ids.indexOf(id);
      expect(resultIndex).not.toBe(-1);
      expect(result.documents[resultIndex]).toBe(updatedContents[index]);
      expect(result.metadatas[resultIndex].importance).toBe(
        updatedMetadatas[index].importance
      );
    });
  });

  // 2.5 Test partial metadata updates
  test('should perform partial metadata updates', async () => {
    const targetId = testItems[4].id;

    // First get the current metadata
    const initialData = await collection.get({ ids: [targetId] });
    const currentMetadata = initialData.metadatas[0];

    // Update only certain fields
    const partialUpdate = {
      ...currentMetadata,
      importance: 7,
      newField: "added value"
    };

    await collection.update({
      ids: [targetId],
      metadatas: [partialUpdate]
    });

    // Verify the partial update
    const result = await collection.get({ ids: [targetId] });

    expect(result.metadatas[0].importance).toBe(7);
    expect(result.metadatas[0].newField).toBe("added value");

    // Other fields should remain unchanged
    expect(result.metadatas[0].category).toBe(currentMetadata.category);
    expect(result.metadatas[0].timestamp).toBe(currentMetadata.timestamp);
  });

  // 2.6 Test error handling for updating non-existent IDs
  test('should handle updating non-existent IDs', async () => {
    const nonExistentId = "non-existent-id";

    // This should throw an error
    await expect(
      collection.update({
        ids: [nonExistentId],
        documents: ["This should fail"]
      })
    ).rejects.toThrow();
  });

  // 2.7 Test error handling for mismatched arrays
  test('should handle mismatched arrays in updates', async () => {
    // Try to update with mismatched lengths of ids and documents
    await expect(
      collection.update({
        ids: [testItems[0].id, testItems[1].id],
        documents: ["Only one document"]
      })
    ).rejects.toThrow();
  });

  // 2.8 Test upsert operation (update or insert)
  test('should upsert entries correctly', async () => {
    // Create a new ID that doesn't exist yet
    const newId = "new-upsert-item";
    const existingId = testItems[0].id;

    // Upsert both new and existing items
    await collection.upsert({
      ids: [newId, existingId],
      documents: ["This is a new item", "This is an updated existing item"],
      metadatas: [
        { category: "upsert-test", importance: 3 },
        { category: testItems[0].category, importance: 4 }
      ]
    });

    // Verify the results
    const result = await collection.get({ 
      ids: [newId, existingId] 
    });

    expect(result.ids).toHaveLength(2);
    expect(result.ids).toContain(newId);
    expect(result.ids).toContain(existingId);

    // Check new item
    const newItemIndex = result.ids.indexOf(newId);
    expect(result.documents[newItemIndex]).toBe("This is a new item");
    expect(result.metadatas[newItemIndex].category).toBe("upsert-test");

    // Check updated item
    const existingItemIndex = result.ids.indexOf(existingId);
    expect(result.documents[existingItemIndex]).toBe("This is an updated existing item");
    expect(result.metadatas[existingItemIndex].importance).toBe(4);
  });

  // 2.9 Test handling concurrent updates
  test('should handle concurrent updates correctly', async () => {
    const targetId = testItems[2].id;

    // Create multiple update operations
    const updatePromises = [];

    // Push 5 concurrent update operations
    for (let i = 0; i < 5; i++) {
      updatePromises.push(
        collection.update({
          ids: [targetId],
          documents: [`Concurrent update ${i}`],
          metadatas: [{ importance: i + 1 }]
        })
      );
    }

    // Execute all updates concurrently
    await Promise.all(updatePromises);

    // Verify the item was updated (we can't predict which update wins)
    const result = await collection.get({ ids: [targetId] });

    expect(result.ids).toHaveLength(1);
    expect(result.documents[0]).toMatch(/^Concurrent update \d$/);
    expect(result.metadatas[0].importance).toBeGreaterThanOrEqual(1);
    expect(result.metadatas[0].importance).toBeLessThanOrEqual(5);
  });
});
