## Testing Notion Integration

Let's create tests for the Notion database operations. We'll start by testing the schema retrieval and then move on to CRUD operations.

### Testing Schema Retrieval

Create a test file at `test/notion/schema-routes.test.js`:

```javascript
const request = require('supertest');
const nock = require('nock');
const app = require('../../index.cjs'); // Adjust the path as needed
const { mockNotionResponses } = require('../mocks');

describe('Notion Schema Routes', () => {
  beforeAll(() => {
    // Set up nock to intercept external requests
    nock.disableNetConnect();
    nock.enableNetConnect('127.0.0.1');
  });

  afterAll(() => {
    nock.cleanAll();
    nock.enableNetConnect();
  });

  afterEach(() => {
    nock.cleanAll();
  });

  test('GET /notion/databases/getschema - Should retrieve database schema', async () => {
    // Mock the Notion API response
    nock('https://api.notion.com')
      .get(/v1\/databases\/test-project-tracker-id/)
      .reply(200, mockNotionResponses.retrieveDatabase);

    // Make request to our API
    const response = await request(app)
      .get('/notion/databases/getschema')
      .query({ database: 'PROJECT_TRACKER' });

    // Verify response
    expect(response.status).toBe(200);
    expect(response.body).toHaveProperty('schema');
    expect(response.body.schema).toHaveProperty('Feature');
    expect(response.body.schema.Feature.type).toBe('title');
    expect(response.body.schema).toHaveProperty('Status');
    expect(response.body.schema.Status.type).toBe('select');
  });

  test('GET /notion/databases/getschema - Should handle missing database parameter', async () => {
    const response = await request(app)
      .get('/notion/databases/getschema');

    expect(response.status).toBe(400);
    expect(response.body).toHaveProperty('error', 'Missing database parameter');
  });

  test('GET /notion/databases/getschema - Should handle unknown database', async () => {
    const response = await request(app)
      .get('/notion/databases/getschema')
      .query({ database: 'UNKNOWN_DB' });

    expect(response.status).toBe(400);
    expect(response.body).toHaveProperty('error', 'Unknown database: UNKNOWN_DB');
  });

  test('GET /notion/databases/getschema - Should handle API errors', async () => {
    // Mock Notion API error
    nock('https://api.notion.com')
      .get(/v1\/databases\/test-project-tracker-id/)
      .reply(500, { message: 'Notion API Error' });

    const response = await request(app)
      .get('/notion/databases/getschema')
      .query({ database: 'PROJECT_TRACKER' });

    expect(response.status).toBe(500);
    expect(response.body).toHaveProperty('error', 'Failed to retrieve schema');
  });
});
