        id: 'long-content-page-id',
        properties: {
          title: [{ text: { content: 'Long Content Test' } }]
        }
      });

    const response = await request(app)
      .put('/notion/pages/createpage')
      .send({
        title: 'Long Content Test',
        content: longContent
      });

    // Notion has limits, but our API should handle it gracefully
    expect(response.status).toBe(200).or.toBe(413).or.toBe(500);

    if (response.status === 200) {
      expect(response.body).toHaveProperty('id', 'long-content-page-id');
    } else {
      expect(response.body).toHaveProperty('error');
    }
  });
});
