# Migrating Node.js APIs to Next.js with TypeScript

This guide provides a comprehensive approach to migrating your existing Node.js Express APIs (Notion and GitHub integrations) to Next.js API routes with TypeScript. We'll focus on maintaining functionality while improving type safety and leveraging Next.js features.

## Table of Contents

1. [Understanding Next.js API Routes](#understanding-nextjs-api-routes)
2. [TypeScript Type Definitions](#typescript-type-definitions)
3. [API Route Structure](#api-route-structure)
4. [Environment Variables](#environment-variables)
5. [Authentication Handling](#authentication-handling)
6. [Utility Function Migration](#utility-function-migration)
7. [Error Handling](#error-handling)
8. [Route-by-Route Migration Guide](#route-by-route-migration-guide)

## Understanding Next.js API Routes

Next.js API routes work differently from Express routes:

- Located in the `/pages/api/` directory (Next.js 12 and earlier) or `/app/api/` (App Router in Next.js 13+)
- Each file becomes an endpoint based on its path
- No need for a separate Express server or `listen()` call
- Built-in parsing of JSON request bodies
- Different middleware pattern

Let's look at a basic comparison:

**Express (current):**
```javascript
// server.js
const express = require('express');
const app = express();
app.use(express.json());

app.get('/api/health', (req, res) => {
  res.json({ status: 'ok' });
});

app.listen(3000);
```

**Next.js (target):**
```typescript
// pages/api/health.ts
import type { NextApiRequest, NextApiResponse } from 'next';

type HealthResponse = {
  status: string;
};

export default function handler(
  req: NextApiRequest,
  res: NextApiResponse<HealthResponse>
) {
  res.status(200).json({ status: 'ok' });
}
```

## TypeScript Type Definitions

Let's define the core TypeScript interfaces you'll need based on your existing code:

```typescript
// types/notion.ts
export interface NotionPage {
  id: string;
  url: string;
  created_time: string;
  last_edited_time: string;
  properties: Record<string, NotionProperty>;
}

export interface NotionProperty {
  id: string;
  type: string;
  title?: Array<{ text: { content: string } }>;
  rich_text?: Array<{ text: { content: string } }>;
  select?: { name: string };
  multi_select?: Array<{ name: string }>;
  date?: { start: string; end?: string };
  checkbox?: boolean;
  number?: number;
  // Add other property types as needed
}

export interface NotionDatabaseSchema {
  [key: string]: {
    id: string;
    name: string;
    type: string;
    options?: Array<{ name: string; id: string }>;
  };
}

// types/github.ts
export interface GitHubIssue {
  title: string;
  body?: string;
}

export interface GitHubIssueUpdate {
  issue_number: number;
  title?: string;
  body?: string;
  state?: 'open' | 'closed';
}

export interface GitHubFile {
  path: string;
  content: string;
  message: string;
  branch?: string;
}

export interface GitHubFileDelete {
  path: string;
  message: string;
  branch?: string;
}

// types/api.ts
export interface ErrorResponse {
  error: string;
  message?: string;
  status?: number;
}

export interface SuccessResponse {
  success: boolean;
  [key: string]: any;
}
```

## API Route Structure

Let's design the folder structure for your Next.js API routes:

```
/pages/api/
  /github/
    issue.ts
    issues.ts
    file.ts
    delete-file.ts
  /notion/
    /databases/
      getschema.ts
      createentry.ts
      updateentry.ts
      deleteentry.ts
      listentries.ts
      readentry.ts
    /memory/
      creatememory.ts
      updatememory.ts
      deletememory.ts
      listmemories.ts
      readmemory.ts
    /pages/
      createpage.ts
      updatepage.ts
      deletepage.ts
      listpages.ts
      readpage.ts
  /health/
    status.ts
    statusNotion.ts
    statusGithub.ts
    statusComplete.ts
  /utils/
    (shared utility functions)
```

Let's implement a sample route conversion:

```typescript
// pages/api/github/issue.ts
import type { NextApiRequest, NextApiResponse } from 'next';
import { GitHubIssue, ErrorResponse, SuccessResponse } from '../../../types/api';
import { handleRateLimit } from '../../../lib/github-utils';
import axios from 'axios';

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse<SuccessResponse | ErrorResponse>
) {
  // Only allow PUT and PATCH methods
  if (req.method !== 'PUT' && req.method !== 'PATCH') {
    return res.status(405).json({ error: 'Method not allowed' });
  }

  const githubToken = process.env.GITHUB_TOKEN;
  const repoOwner = process.env.GITHUB_REPO_OWNER;
  const repoName = process.env.GITHUB_REPO_NAME;

  if (!githubToken) {
    return res.status(401).json({ error: 'GitHub token not configured' });
  }

  const headers = {
    Authorization: `Bearer ${githubToken}`,
    'X-GitHub-Api-Version': '2022-11-28',
    'User-Agent': 'next-js-api',
  };

  try {
    // Handle creating a new issue (PUT)
    if (req.method === 'PUT') {
      const { title, body } = req.body as GitHubIssue;

      if (!title) {
        return res.status(400).json({ error: 'Title is required' });
      }

      const response = await axios.post(
        `https://api.github.com/repos/${repoOwner}/${repoName}/issues`,
        { title, body },
        { headers }
      );

      return res.status(200).json({ 
        success: true, 
        issueUrl: response.data.html_url 
      });
    } 
    // Handle updating an issue (PATCH)
    else if (req.method === 'PATCH') {
      const { issue_number, title, body, state } = req.body;

      if (!issue_number) {
        return res.status(400).json({ error: 'Issue number is required' });
      }

      const response = await axios.patch(
        `https://api.github.com/repos/${repoOwner}/${repoName}/issues/${issue_number}`,
        { title, body, state },
        { headers }
      );

      return res.status(200).json({ 
        success: true, 
        updated: response.data 
      });
    }
  } catch (error) {
    if (axios.isAxiosError(error)) {
      return handleRateLimit(error, res);
    }

    return res.status(500).json({ 
      error: 'Error with GitHub API',
      message: error instanceof Error ? error.message : 'Unknown error'
    });
  }
}
```

## Environment Variables

Next.js handles environment variables differently from Node.js:

1. Create a `.env.local` file in the root directory (for local development)
2. Create `.env.production` for production values
3. Prefix variables with `NEXT_PUBLIC_` if they need to be accessible in the browser

Let's create a type-safe way to access environment variables:

```typescript
// lib/env.ts
export function getEnvVariable(key: string): string {
  const value = process.env[key];
  if (!value) {
    // In development, throw an error to help catch missing variables
    if (process.env.NODE_ENV === 'development') {
      throw new Error(`Missing environment variable: ${key}`);
    }
    // In production, log an error but avoid crashing
    console.error(`Missing environment variable: ${key}`);
    return '';
  }
  return value;
}

// Type-safe environment variable access
export const env = {
  // Notion
  NOTION_TOKEN: getEnvVariable('NOTION_TOKEN'),
  NOTION_PARENT_PAGE_ID: getEnvVariable('NOTION_PARENT_PAGE_ID'),
  PROJECT_TRACKER: getEnvVariable('PROJECT_TRACKER'),
  GPT_MEMORY_DB: getEnvVariable('GPT_MEMORY_DB'),

  // GitHub
  GITHUB_TOKEN: getEnvVariable('GITHUB_TOKEN'),
  GITHUB_REPO_NAME: getEnvVariable('GITHUB_REPO_NAME'),
  GITHUB_REPO_OWNER: getEnvVariable('GITHUB_REPO_OWNER'),

  // Check variable exists but return empty string if it doesn't (for optional vars)
  getOptional(key: string): string {
    return process.env[key] || '';
  }
};
```

You'll also need to configure environment variables in your `next.config.js`:

```javascript
// next.config.js
module.exports = {
  env: {
    // You can set defaults here, but it's better to use .env files
  },
};
```

## Authentication Handling

Since you're using token-based authentication for APIs, you can implement middleware for authentication:

```typescript
// lib/middleware/auth.ts
import { NextApiRequest, NextApiResponse } from 'next';
import { ErrorResponse } from '../../types/api';

export type NextApiHandler<T = any> = (
  req: NextApiRequest,
  res: NextApiResponse<T | ErrorResponse>
) => Promise<void> | void;

export function withGitHubAuth<T = any>(handler: NextApiHandler<T>): NextApiHandler<T> {
  return async (req, res) => {
    if (!process.env.GITHUB_TOKEN) {
      return res.status(401).json({ 
        error: 'GitHub token not configured' 
      });
    }
    return handler(req, res);
  };
}

export function withNotionAuth<T = any>(handler: NextApiHandler<T>): NextApiHandler<T> {
  return async (req, res) => {
    if (!process.env.NOTION_TOKEN) {
      return res.status(401).json({ 
        error: 'Notion token not configured' 
      });
    }
    return handler(req, res);
  };
}
```

