Let's also migrate the GitHub utils:

```typescript
// lib/github-utils.ts
import { NextApiResponse } from 'next';
import { ErrorResponse } from '../types/api';
import axios, { AxiosError } from 'axios';

// Helper function to handle rate limits
export function handleRateLimit(
  error: AxiosError, 
  res: NextApiResponse<ErrorResponse>
) {
  if (error.response?.status === 403 && 
      error.response?.data?.message?.includes('API rate limit exceeded')) {
    return res.status(429).json({ 
      error: "GitHub API rate limit exceeded, please try again later",
      reset_at: error.response.headers['x-ratelimit-reset'] as string
    });
  }

  // Handle other errors
  const status = error.response?.status || 500;
  return res.status(status).json({
    error: error.response?.data?.message || error.message,
    status: status,
    documentation_url: error.response?.data?.documentation_url
  });
}

// Create base axios instance for GitHub API calls
export function createGitHubClient() {
  const githubToken = process.env.GITHUB_TOKEN;

  return axios.create({
    baseURL: 'https://api.github.com',
    headers: {
      Authorization: `Bearer ${githubToken}`,
      'X-GitHub-Api-Version': '2022-11-28',
      'User-Agent': 'next-js-api',
    },
    timeout: 10000 // 10 seconds
  });
}
