## Error Handling

Let's implement a consistent error handling pattern:

```typescript
// lib/error-handler.ts
import { NextApiResponse } from 'next';
import { ErrorResponse } from '../types/api';

export enum ErrorType {
  VALIDATION_ERROR = 'VALIDATION_ERROR',
  NOT_FOUND = 'NOT_FOUND',
  AUTHENTICATION_ERROR = 'AUTHENTICATION_ERROR',
  AUTHORIZATION_ERROR = 'AUTHORIZATION_ERROR',
  RATE_LIMIT_ERROR = 'RATE_LIMIT_ERROR',
  EXTERNAL_API_ERROR = 'EXTERNAL_API_ERROR',
  SERVER_ERROR = 'SERVER_ERROR'
}

interface ApiError extends Error {
  type: ErrorType;
  statusCode: number;
  details?: any;
}

export function createApiError(
  message: string,
  type: ErrorType,
  statusCode: number,
  details?: any
): ApiError {
  const error = new Error(message) as ApiError;
  error.type = type;
  error.statusCode = statusCode;
  error.details = details;
  return error;
}

export function handleApiError(
  error: unknown,
  res: NextApiResponse<ErrorResponse>,
  defaultMessage = 'An unexpected error occurred'
) {
  console.error('API Error:', error);

  // If it's one of our custom API errors
  if (error && typeof error === 'object' && 'type' in error) {
    const apiError = error as ApiError;
    return res.status(apiError.statusCode).json({
      error: apiError.type,
      message: apiError.message,
      details: apiError.details
    });
  }

  // Handle axios errors
  if (axios.isAxiosError(error)) {
    const status = error.response?.status || 500;
    return res.status(status).json({
      error: 'EXTERNAL_API_ERROR',
      message: error.response?.data?.message || error.message,
      status
    });
  }

  // Generic error
  return res.status(500).json({
    error: 'SERVER_ERROR',
    message: error instanceof Error ? error.message : defaultMessage
  });
}
```

## Route-by-Route Migration Guide

Let's go through an example of migrating a few key routes from your existing codebase:

### 1. Health Check API

**Current (Express):**
