// pages/api/notion/databases/getschema.ts
import type { NextApiRequest, NextApiResponse } from 'next';
import { getDatabaseSchema } from '../../../../lib/schema-detection';
import { withNotionAuth } from '../../../../lib/middleware/auth';
import { ErrorResponse } from '../../../../types/api';
import { NotionDatabaseSchema } from '../../../../types/notion';
import { env } from '../../../../lib/env';

interface SchemaResponse {
  database: string;
  schema: NotionDatabaseSchema;
}

async function handler(
  req: NextApiRequest,
  res: NextApiResponse<SchemaResponse | ErrorResponse>
) {
  if (req.method !== 'GET') {
    return res.status(405).json({ error: 'Method not allowed' });
  }

  const { database } = req.query;

  if (!database || typeof database !== 'string') {
    return res.status(400).json({ error: 'Missing database parameter' });
  }

  const dbId = env.getOptional(database);

  if (!dbId) {
    return res.status(400).json({
      error: `Unknown database: ${database}`,
      message: `Ensure ${database} is defined as an environment variable`
    });
  }

  try {
    const schema = await getDatabaseSchema(dbId);
    return res.status(200).json({ database, schema });
  } catch (err) {
    console.error(`Error retrieving schema for ${database}:`, err);
    return res.status(500).json({
      error: 'Failed to retrieve schema',
      message: err instanceof Error ? err.message : 'Unknown error'
    });
  }
}

export default withNotionAuth(handler);
```

