/**
 * Example implementation of the ChromaDBService
 * Include this in your guide for reference
 */
export interface MemoryItem {
  id: string;
  content: string;
  metadata?: Record<string, any>;
}

export class ChromaDBService {
  private client: ChromaClient;
  private collectionName: string;

  constructor(client: ChromaClient, collectionName: string) {
    this.client = client;
    this.collectionName = collectionName;
  }

  // Get collection instance (helper method)
  private async getCollection(): Promise<Collection> {
    return await this.client.getCollection({ name: this.collectionName });
  }

  // Add a single item
  async addItem(item: MemoryItem): Promise<void> {
    const collection = await this.getCollection();
    await collection.add({
      ids: [item.id],
      documents: [item.content],
      metadatas: [item.metadata || {}]
    });
  }

  // Add multiple items
  async addItems(items: MemoryItem[]): Promise<void> {
    const collection = await this.getCollection();
    await collection.add({
      ids: items.map(item => item.id),
      documents: items.map(item => item.content),
      metadatas: items.map(item => item.metadata || {})
    });
  }

  // Get all items
  async getAllItems(): Promise<MemoryItem[]> {
    const collection = await this.getCollection();
    const result = await collection.get();

    return result.ids.map((id, index) => ({
      id: id.toString(),
      content: result.documents[index]?.toString() || '',
      metadata: result.metadatas?.[index] || {}
    }));
  }

  // Get paginated items
  async getItems(offset: number, limit: number): Promise<MemoryItem[]> {
    const collection = await this.getCollection();
    const result = await collection.get(undefined, { offset, limit });

    return result.ids.map((id, index) => ({
      id: id.toString(),
      content: result.documents[index]?.toString() || '',
      metadata: result.metadatas?.[index] || {}
    }));
  }

  // Get items by filter
  async getItemsByFilter(filter: Record<string, any>): Promise<MemoryItem[]> {
    const collection = await this.getCollection();
    const result = await collection.get({ where: filter });

    return result.ids.map((id, index) => ({
      id: id.toString(),
      content: result.documents[index]?.toString() || '',
      metadata: result.metadatas?.[index] || {}
    }));
  }

  // Get items sorted by a field
  async getItemsSorted(sortBy: string, order: 'asc' | 'desc'): Promise<MemoryItem[]> {
    // ChromaDB doesn't have native sorting, so we fetch and sort manually
    const allItems = await this.getAllItems();

    return allItems.sort((a, b) => {
      const valA = a.metadata?.[sortBy];
      const valB = b.metadata?.[sortBy];

      if (valA === undefined || valB === undefined) return 0;

      if (order === 'asc') {
        return valA < valB ? -1 : valA > valB ? 1 : 0;
      } else {
        return valA > valB ? -1 : valA < valB ? 1 : 0;
      }
    });
  }

  // Get filtered and sorted items
  async getItemsFilteredAndSorted(
    filter: Record<string, any>,
    sortBy: string,
    order: 'asc' | 'desc'
  ): Promise<MemoryItem[]> {
    const filteredItems = await this.getItemsByFilter(filter);

    return filteredItems.sort((a, b) => {
      const valA = a.metadata?.[sortBy];
      const valB = b.metadata?.[sortBy];

      if (valA === undefined || valB === undefined) return 0;

      if (order === 'asc') {
        return valA < valB ? -1 : valA > valB ? 1 : 0;
      } else {
        return valA > valB ? -1 : valA < valB ? 1 : 0;
      }
    });
  }

  // Delete a single item
  async deleteItem(id: string): Promise<void> {
    const collection = await this.getCollection();
    await collection.delete({ ids: [id] });
  }

  // Delete multiple items
  async deleteItems(ids: string[]): Promise<void> {
    const collection = await this.getCollection();
    await collection.delete({ ids });
  }

  // Delete items by filter
  async deleteItemsByFilter(filter: Record<string, any>): Promise<void> {
    const collection = await this.getCollection();
    await collection.delete({ where: filter });
  }
}

