## 2. Schema Design

ChromaDB is a vector database designed to store embeddings along with metadata. Here's a minimalist schema for conversation memory:

### Collection Structure

We'll create separate collections for different GPT personalities:

1. `ableGPT` - For storing AbleGPT conversation memory
2. `renascendGPT` - For storing RenascendGPT conversation memory

Each collection will store documents with:
- **Embedding**: Vector representation of the conversation
- **Metadata**: 
  - `userId`: Unique identifier for the user
  - `timestamp`: When the conversation occurred
  - `type`: Message type (user/assistant)
  - `topic`: Detected topic of conversation (optional)
  - `tags`: Array of tags for categorization (optional)
- **Document**: The actual conversation text

### Schema Implementation

```javascript
// app/lib/schema.js
export const COLLECTIONS = {
  ABLE_GPT: 'ableGPT',
  RENASCEND_GPT: 'renascendGPT'
};

export const MEMORY_TYPES = {
  USER_MESSAGE: 'user_message',
  ASSISTANT_RESPONSE: 'assistant_response',
  SYSTEM_INSTRUCTION: 'system_instruction'
};

export const DEFAULT_METADATA = {
  userId: 'anonymous',
  timestamp: new Date().toISOString(),
  type: MEMORY_TYPES.USER_MESSAGE,
  topic: 'general',
  tags: []
};
```

## 3. ChromaDB Utilities

Let's create utility functions for common ChromaDB operations:

```javascript
// app/lib/chroma-client.js
import { ChromaClient } from 'chromadb';

// Configuration with fallbacks
const config = {
  path: process.env.CHROMA_DB_PATH || './data/chromadb',
  apiUrl: process.env.CHROMA_API_URL,
  apiKey: process.env.CHROMA_API_KEY
};

// Singleton pattern for ChromaDB client
let clientInstance = null;

/**
 * Get ChromaDB client instance (singleton)
 */
export const getChromaClient = async () => {
  if (clientInstance) return clientInstance;

  // Use API URL if provided, otherwise use local path
  if (config.apiUrl) {
    clientInstance = new ChromaClient({
      path: config.apiUrl,
      auth: config.apiKey ? { token: config.apiKey } : undefined
    });
  } else {
    clientInstance = new ChromaClient({ path: config.path });
  }

  return clientInstance;
};

/**
 * Get or create a collection
 * @param {string} name - Collection name
 * @param {object} options - Collection options
 * @returns {Promise<Collection>}
 */
export const getCollection = async (name, options = {}) => {
  const client = await getChromaClient();

  try {
    return await client.getCollection({ name });
  } catch (error) {
    // Collection doesn't exist, create it
    return await client.createCollection({
      name,
      metadata: options.metadata || { description: `${name} memory collection` }
    });
  }
};

/**
 * Delete a collection if it exists
 * @param {string} name - Collection name
 * @returns {Promise<boolean>}
 */
export const deleteCollection = async (name) => {
  const client = await getChromaClient();
  try {
    await client.deleteCollection({ name });
    return true;
  } catch (error) {
    console.error(`Error deleting collection ${name}:`, error);
    return false;
  }
};

/**
 * List all collections
 * @returns {Promise<Array>}
 */
export const listCollections = async () => {
  const client = await getChromaClient();
  try {
    return await client.listCollections();
  } catch (error) {
    console.error('Error listing collections:', error);
    return [];
  }
};
```

## 4. Memory Management

Now, let's implement memory storage and retrieval functions:

```javascript
// app/lib/memory-manager.js
import { OpenAI } from 'openai';
import { getCollection } from './chroma-client';
import { COLLECTIONS, DEFAULT_METADATA, MEMORY_TYPES } from './schema';

// Initialize OpenAI client for embeddings
const openai = new OpenAI({
  apiKey: process.env.OPENAI_API_KEY
});

/**
 * Generate embedding for text using OpenAI
 * @param {string} text - Text to embed
 * @returns {Promise<Array<number>>}
 */
export const generateEmbedding = async (text) => {
  try {
    const response = await openai.embeddings.create({
      model: 'text-embedding-ada-002',
      input: text
    });

    return response.data[0].embedding;
  } catch (error) {
    console.error('Error generating embedding:', error);
    throw error;
  }
};

/**
 * Store a memory in ChromaDB
 * @param {string} collectionName - Collection name (e.g., 'ableGPT')
 * @param {string} text - Text content to store
 * @param {object} metadata - Additional metadata
 * @returns {Promise<string>} - ID of stored memory
 */
export const storeMemory = async (collectionName, text, metadata = {}) => {
  // Generate a unique ID
  const id = `mem_${Date.now()}_${Math.random().toString(36).substring(2, 10)}`;

  // Generate embedding
  const embedding = await generateEmbedding(text);

  // Get collection
  const collection = await getCollection(collectionName);

  // Merge with default metadata
  const finalMetadata = {
    ...DEFAULT_METADATA,
    ...metadata,
    timestamp: new Date().toISOString()
  };

  // Add to collection
  await collection.add({
    ids: [id],
    embeddings: [embedding],
    metadatas: [finalMetadata],
    documents: [text]
  });

  return id;
};

/**
 * Store a user message
 * @param {string} personality - 'ableGPT' or 'renascendGPT'
 * @param {string} userId - User identifier
 * @param {string} message - User message
 * @returns {Promise<string>} - Memory ID
 */
export const storeUserMessage = async (personality, userId, message) => {
  const collectionName = personality === 'ableGPT' ? 
    COLLECTIONS.ABLE_GPT : COLLECTIONS.RENASCEND_GPT;

  return storeMemory(collectionName, message, {
    userId,
    type: MEMORY_TYPES.USER_MESSAGE
  });
};

/**
 * Store an assistant response
 * @param {string} personality - 'ableGPT' or 'renascendGPT'
 * @param {string} userId - User identifier
 * @param {string} response - Assistant response
 * @returns {Promise<string>} - Memory ID
 */
export const storeAssistantResponse = async (personality, userId, response) => {
  const collectionName = personality === 'ableGPT' ? 
    COLLECTIONS.ABLE_GPT : COLLECTIONS.RENASCEND_GPT;

  return storeMemory(collectionName, response, {
    userId,
    type: MEMORY_TYPES.ASSISTANT_RESPONSE
  });
};

/**
 * Search for similar memories
 * @param {string} collectionName - Collection name
 * @param {string} query - Search query
 * @param {object} options - Search options
 * @returns {Promise<Array>} - Similar memories
 */
export const searchMemories = async (collectionName, query, options = {}) => {
  // Default options
  const {
    limit = 5,
    userId = null,
    minScore = 0.7,
    includeEmbeddings = false
  } = options;

  // Generate embedding for query
  const queryEmbedding = await generateEmbedding(query);

  // Get collection
  const collection = await getCollection(collectionName);

  // Build filter if userId is provided
  const filter = userId ? { userId } : undefined;

  // Perform search
  const results = await collection.query({
    queryEmbeddings: [queryEmbedding],
    nResults: limit,
    where: filter
  });

  // Format results
  return results.ids[0].map((id, i) => {
    const score = results.distances[0][i];
    // Skip results below minimum score
    if (score > minScore) return null;

    return {
      id,
      text: results.documents[0][i],
      metadata: results.metadatas[0][i],
      distance: score,
      embedding: includeEmbeddings ? results.embeddings?.[0][i] : undefined
    };
  }).filter(Boolean); // Remove null entries
};

/**
 * Get user conversation history
 * @param {string} personality - 'ableGPT' or 'renascendGPT'
 * @param {string} userId - User identifier
 * @param {number} limit - Max number of messages
 * @returns {Promise<Array>} - Conversation history
 */
export const getUserHistory = async (personality, userId, limit = 20) => {
  const collectionName = personality === 'ableGPT' ? 
    COLLECTIONS.ABLE_GPT : COLLECTIONS.RENASCEND_GPT;

  // Get collection
  const collection = await getCollection(collectionName);

  // Query for user's messages and sort by timestamp
  const results = await collection.get({
    where: { userId },
    limit
  });

  // Sort by timestamp (newest first)
  return results.ids.map((id, i) => ({
    id,
    text: results.documents[i],
    metadata: results.metadatas[i]
  })).sort((a, b) => {
    return new Date(b.metadata.timestamp) - new Date(a.metadata.timestamp);
  });
};
```

## 5. Session Context Management

For maintaining conversation context across sessions:

```javascript
// app/lib/context-manager.js
import { searchMemories, getUserHistory } from './memory-manager';
import { COLLECTIONS } from './schema';

/**
 * Get relevant context for the current conversation
 * @param {string} personality - 'ableGPT' or 'renascendGPT'
 * @param {string} userId - User identifier
 * @param {string} currentQuery - Current user query
 * @param {number} historyLimit - Max history items
 * @param {number} relevantLimit - Max relevant items
 * @returns {Promise<object>} - Context object
 */
export const getConversationContext = async (
  personality,
  userId,
  currentQuery,
  historyLimit = 10,
  relevantLimit = 3
) => {
  const collectionName = personality === 'ableGPT' ? 
    COLLECTIONS.ABLE_GPT : COLLECTIONS.RENASCEND_GPT;

  // Get recent conversation history
  const history = await getUserHistory(personality, userId, historyLimit);

  // Get relevant past conversations
  const relevantMemories = await searchMemories(collectionName, currentQuery, {
    limit: relevantLimit,
    userId
  });

  // Format context for the AI
  const recentMessages = history.map(item => ({
    role: item.metadata.type === 'user_message' ? 'user' : 'assistant',
    content: item.text
  }));

  const relevantContext = relevantMemories.map(memory => 
    `Previous relevant conversation: ${memory.text}`
  ).join('\n\n');

  return {
    recentMessages,
    relevantContext,
    fullContext: `${relevantContext}\n\n${JSON.stringify(recentMessages)}`,
    history,
    relevantMemories
  };
};

/**
 * Format conversation for API request
 * @param {object} context - Context from getConversationContext
 * @param {string} systemPrompt - System prompt
 * @returns {Array} - Formatted messages for API
 */
export const formatConversationForAPI = (context, systemPrompt) => {
  const messages = [
    { role: 'system', content: systemPrompt }
  ];

  // Add relevant context if available
  if (context.relevantContext) {
    messages.push({
      role: 'system',
      content: `Additional context from previous conversations:\n${context.relevantContext}`
    });
  }

  // Add recent conversation history
  messages.push(...context.recentMessages);

  return messages;
};
```

## 6. Performance Optimization

ChromaDB performance can be optimized in several ways:

1. **Batch Processing**: Always batch operations when possible:

```javascript
// Batch insert example
export const storeBatchMemories = async (collectionName, items) => {
  const collection = await getCollection(collectionName);

  const embeddings = await Promise.all(
    items.map(item => generateEmbedding(item.text))
  );

  await collection.add({
    ids: items.map(item => item.id),
    embeddings,
    metadatas: items.map(item => item.metadata),
    documents: items.map(item => item.text)
  });
};
```

2. **Embedding Caching**: Cache embeddings for frequently used text:

```javascript
// Simple in-memory embedding cache
const embeddingCache = new Map();

export const generateEmbeddingWithCache = async (text) => {
  // Create a cache key (can be a hash of the text)
  const cacheKey = text.substring(0, 100);

  // Check cache first
  if (embeddingCache.has(cacheKey)) {
    return embeddingCache.get(cacheKey);
  }

  // Generate new embedding
  const embedding = await generateEmbedding(text);

  // Cache the result (with a maximum cache size)
  if (embeddingCache.size > 1000) {
    // Remove oldest entry
    const firstKey = embeddingCache.keys().next().value;
    embeddingCache.delete(firstKey);
  }
  embeddingCache.set(cacheKey, embedding);

  return embedding;
};
```

3. **Index Optimization**: Configure index parameters for your use case:

```javascript
// Create collection with optimized parameters
export const createOptimizedCollection = async (name, options = {}) => {
  const client = await getChromaClient();

  return await client.createCollection({
    name,
    metadata: options.metadata || { description: `${name} memory collection` },
    embeddingFunction: options.embeddingFunction,
    // Adjust these based on your data characteristics
    hnsw_config: {
      ef_construction: 100,  // Higher = more accurate but slower indexing
      M: 16                  // Number of connections per element
    }
  });
};
```

