```typescript
// src/lib/chroma/memory-manager.ts
import { OpenAI } from 'openai';
import { getCollection } from './client';
import { 
  COLLECTIONS, 
  DEFAULT_METADATA, 
  MEMORY_TYPES, 
  MemoryMetadata, 
  CollectionType,
  MemoryType 
} from './schema';

// Initialize OpenAI client for embeddings
const openai = new OpenAI({
  apiKey: process.env.OPENAI_API_KEY
});

interface SearchOptions {
  limit?: number;
  userId?: string | null;
  minScore?: number;
  includeEmbeddings?: boolean;
}

interface MemoryResult {
  id: string;
  text: string;
  metadata: MemoryMetadata;
  distance: number;
  embedding?: number[];
}

/**
 * Generate embedding for text using OpenAI
 * @param text - Text to embed
 * @returns Embedding array
 */
export const generateEmbedding = async (text: string): Promise<number[]> => {
  try {
    const response = await openai.embeddings.create({
      model: 'text-embedding-ada-002',
      input: text
    });

    return response.data[0].embedding;
  } catch (error) {
    console.error('Error generating embedding:', error);
    throw error;
  }
};

/**
 * Store a memory in ChromaDB
 * @param collectionName - Collection name
 * @param text - Text content to store
 * @param metadata - Additional metadata
 * @returns ID of stored memory
 */
export const storeMemory = async (
  collectionName: string, 
  text: string, 
  metadata: Partial<MemoryMetadata> = {}
): Promise<string> => {
  // Generate a unique ID
  const id = `mem_${Date.now()}_${Math.random().toString(36).substring(2, 10)}`;

  // Generate embedding
  const embedding = await generateEmbedding(text);

  // Get collection
  const collection = await getCollection(collectionName);

  // Merge with default metadata
  const finalMetadata: MemoryMetadata = {
    ...DEFAULT_METADATA,
    ...metadata,
    timestamp: new Date().toISOString()
  };

  // Add to collection
  await collection.add({
    ids: [id],
    embeddings: [embedding],
    metadatas: [finalMetadata],
    documents: [text]
  });

  return id;
};

/**
 * Store a user message
 * @param personality - 'ableGPT' or 'renascendGPT'
 * @param userId - User identifier
 * @param message - User message
 * @returns Memory ID
 */
export const storeUserMessage = async (
  personality: string, 
  userId: string, 
  message: string
): Promise<string> => {
  const collectionName = personality === 'ableGPT' ? 
    COLLECTIONS.ABLE_GPT : COLLECTIONS.RENASCEND_GPT;

  return storeMemory(collectionName, message, {
    userId,
    type: MEMORY_TYPES.USER_MESSAGE
  });
};

/**
 * Store an assistant response
 * @param personality - 'ableGPT' or 'renascendGPT'
 * @param userId - User identifier
 * @param response - Assistant response
 * @returns Memory ID
 */
export const storeAssistantResponse = async (
  personality: string, 
  userId: string, 
  response: string
): Promise<string> => {
  const collectionName = personality === 'ableGPT' ? 
    COLLECTIONS.ABLE_GPT : COLLECTIONS.RENASCEND_GPT;

  return storeMemory(collectionName, response, {
    userId,
    type: MEMORY_TYPES.ASSISTANT_RESPONSE
  });
};

/**
 * Search for similar memories
 * @param collectionName - Collection name
 * @param query - Search query
 * @param options - Search options
 * @returns Similar memories
 */
export const searchMemories = async (
  collectionName: string, 
  query: string, 
  options: SearchOptions = {}
): Promise<MemoryResult[]> => {
  // Default options
  const {
    limit = 5,
    userId = null,
    minScore = 0.7,
    includeEmbeddings = false
  } = options;

  // Generate embedding for query
  const queryEmbedding = await generateEmbedding(query);

  // Get collection
  const collection = await getCollection(collectionName);

  // Build filter if userId is provided
  const filter = userId ? { userId } : undefined;

  // Perform search
  const results = await collection.query({
    queryEmbeddings: [queryEmbedding],
    nResults: limit,
    where: filter
  });

  // Format results
  return results.ids[0].map((id, i) => {
    const score = results.distances[0][i];
    // Skip results below minimum score
    if (score > minScore) return null;

    return {
      id,
      text: results.documents[0][i],
      metadata: results.metadatas[0][i],
      distance: score,
      embedding: includeEmbeddings ? results.embeddings?.[0][i] : undefined
    };
  }).filter(Boolean) as MemoryResult[]; // Remove null entries
};

/**
 * Get user conversation history
 * @param personality - 'ableGPT' or 'renascendGPT'
 * @param userId - User identifier
 * @param limit - Max number of messages
 * @returns Conversation history
 */
export const getUserHistory = async (
  personality: string, 
  userId: string, 
  limit: number = 20
): Promise<MemoryResult[]> => {
  const collectionName = personality === 'ableGPT' ? 
    COLLECTIONS.ABLE_GPT : COLLECTIONS.RENASCEND_GPT;

  // Get collection
  const collection = await getCollection(collectionName);

  // Query for user's messages and sort by timestamp
  const results = await collection.get({
    where: { userId },
    limit
  });

  // Sort by timestamp (newest first)
  return results.ids.map((id, i) => ({
    id,
    text: results.documents[i],
    metadata: results.metadatas[i],
    distance: 0 // Not applicable for direct fetch
  })).sort((a, b) => {
    return new Date(b.metadata.timestamp).getTime() - new Date(a.metadata.timestamp).getTime();
  });
};
```

### 4. Context Manager (`src/lib/chroma/context-manager.ts`)

```typescript
// src/lib/chroma/context-manager.ts
import { searchMemories, getUserHistory, MemoryResult } from './memory-manager';
import { COLLECTIONS } from './schema';

interface Message {
  role: 'user' | 'assistant' | 'system';
  content: string;
}

interface ConversationContext {
  recentMessages: Message[];
  relevantContext: string;
  fullContext: string;
  history: MemoryResult[];
  relevantMemories: MemoryResult[];
}

/**
 * Get relevant context for the current conversation
 * @param personality - 'ableGPT' or 'renascendGPT'
 * @param userId - User identifier
 * @param currentQuery - Current user query
 * @param historyLimit - Max history items
 * @param relevantLimit - Max relevant items
 * @returns Context object
 */
export const getConversationContext = async (
  personality: string,
  userId: string,
  currentQuery: string,
  historyLimit: number = 10,
  relevantLimit: number = 3
): Promise<ConversationContext> => {
  const collectionName = personality === 'ableGPT' ? 
    COLLECTIONS.ABLE_GPT : COLLECTIONS.RENASCEND_GPT;

  // Get recent conversation history
  const history = await getUserHistory(personality, userId, historyLimit);

  // Get relevant past conversations
  const relevantMemories = await searchMemories(collectionName, currentQuery, {
    limit: relevantLimit,
    userId
  });

  // Format context for the AI
  const recentMessages: Message[] = history.map(item => ({
    role: item.metadata.type === 'user_message' ? 'user' : 'assistant',
    content: item.text
  }));

  const relevantContext: string = relevantMemories.map(memory => 
    `Previous relevant conversation: ${memory.text}`
  ).join('\n\n');

  return {
    recentMessages,
    relevantContext,
    fullContext: `${relevantContext}\n\n${JSON.stringify(recentMessages)}`,
    history,
    relevantMemories
  };
};

/**
 * Format conversation for API request
 * @param context - Context from getConversationContext
 * @param systemPrompt - System prompt
 * @returns Formatted messages for API
 */
export const formatConversationForAPI = (
  context: ConversationContext, 
  systemPrompt: string
): Message[] => {
  const messages: Message[] = [
    { role: 'system', content: systemPrompt }
  ];

  // Add relevant context if available
  if (context.relevantContext) {
    messages.push({
      role: 'system',
      content: `Additional context from previous conversations:\n${context.relevantContext}`
    });
  }

  // Add recent conversation history
  messages.push(...context.recentMessages);

  return messages;
};
```

By converting all these files to TypeScript, you'll have a consistent and type-safe implementation that aligns with your project structure. The TypeScript versions provide better type safety, IDE support, and will help catch potential errors at compile time rather than runtime.

