// src/lib/chroma/client.ts
import { ChromaClient, Collection } from 'chromadb';

interface ChromaConfig {
  path: string;
  apiUrl?: string;
  apiKey?: string;
}

// Configuration with fallbacks
const config: ChromaConfig = {
  path: process.env.CHROMA_DB_PATH || './data/chromadb',
  apiUrl: process.env.CHROMA_API_URL,
  apiKey: process.env.CHROMA_API_KEY
};

// Singleton pattern for ChromaDB client
let clientInstance: ChromaClient | null = null;

/**
 * Get ChromaDB client instance (singleton)
 */
export const getChromaClient = async (): Promise<ChromaClient> => {
  if (clientInstance) return clientInstance;

  // Use API URL if provided, otherwise use local path
  if (config.apiUrl) {
    // For remote ChromaDB server
    const options: any = { path: config.apiUrl };

    // Add auth if API key is provided
    if (config.apiKey) {
      options.auth = {
        provider: "token", 
        credentials: config.apiKey
      };
    }

    clientInstance = new ChromaClient(options);
  } else {
    // For local ChromaDB instance
    clientInstance = new ChromaClient({ path: config.path });
  }

  return clientInstance;
};

interface CollectionOptions {
  metadata?: Record<string, any>;
}

