  await connectToDatabase();
  return User.findOne({ email });
}

/**
 * Find a user by ID
 */
export async function findUserById(id: string): Promise<IUser | null> {
  await connectToDatabase();
  if (!mongoose.Types.ObjectId.isValid(id)) {
    return null;
  }
  return User.findById(id);
}

/**
 * Create a new user
 */
export async function createUser(userData: Partial<IUser>): Promise<IUser> {
  await connectToDatabase();
  return User.create(userData);
}

/**
 * Update a user
 */
export async function updateUser(id: string, userData: Partial<IUser>): Promise<IUser | null> {
  await connectToDatabase();
  if (!mongoose.Types.ObjectId.isValid(id)) {
    return null;
  }
  return User.findByIdAndUpdate(id, userData, { new: true });
}

/**
 * Delete a user
 */
export async function deleteUser(id: string): Promise<IUser | null> {
  await connectToDatabase();
  if (!mongoose.Types.ObjectId.isValid(id)) {
    return null;
  }
  return User.findByIdAndDelete(id);
}
