## 7. Database Migrations

Creating a simple migration system for MongoDB:

### Migration Framework (`/lib/db/migrations/framework.ts`)

```typescript
import mongoose from 'mongoose';
import { connectToDatabase } from '../index';

// Migration model to track applied migrations
const MigrationSchema = new mongoose.Schema({
  name: { type: String, required: true, unique: true },
  appliedAt: { type: Date, default: Date.now },
});

const Migration = mongoose.models.Migration || 
  mongoose.model('Migration', MigrationSchema);

// Migration interface
export interface IMigration {
  name: string;
  up: () => Promise<void>;
  down: () => Promise<void>;
}

/**
 * Apply migrations that haven't been run yet
 */
export async function applyMigrations(migrations: IMigration[]) {
  await connectToDatabase();

  // Sort migrations by name
  const sortedMigrations = [...migrations].sort((a, b) => 
    a.name.localeCompare(b.name)
  );

  // Get already applied migrations
  const appliedMigrations = await Migration.find({}).lean();
  const appliedMigrationNames = appliedMigrations.map(m => m.name);

  // Filter migrations that need to be applied
  const pendingMigrations = sortedMigrations.filter(
    m => !appliedMigrationNames.includes(m.name)
  );

  if (pendingMigrations.length === 0) {
    console.log('No pending migrations to apply');
    return;
  }

  // Apply each pending migration
  for (const migration of pendingMigrations) {
    try {
      console.log(`Applying migration: ${migration.name}`);
      await migration.up();
      await Migration.create({ name: migration.name });
      console.log(`Migration ${migration.name} applied successfully`);
    } catch (error) {
      console.error(`Failed to apply migration ${migration.name}:`, error);
      throw error;
    }
  }

  console.log(`Applied ${pendingMigrations.length} migrations`);
}

/**
 * Rollback the last applied migration
 */
export async function rollbackMigration() {
  await connectToDatabase();

  // Find the last applied migration
  const lastMigration = await Migration.findOne()
    .sort({ appliedAt: -1 })
    .lean();

  if (!lastMigration) {
    console.log('No migrations to rollback');
    return;
  }

  // Find the migration implementation
  const migrationImplementation = migrations.find(
    m => m.name === lastMigration.name
  );

  if (!migrationImplementation) {
    console.error(`Migration implementation for ${lastMigration.name} not found`);
    return;
  }

  try {
    console.log(`Rolling back migration: ${lastMigration.name}`);
    await migrationImplementation.down();
    await Migration.deleteOne({ name: lastMigration.name });
    console.log(`Migration ${lastMigration.name} rolled back successfully`);
  } catch (error) {
    console.error(`Failed to rollback migration ${lastMigration.name}:`, error);
    throw error;
  }
}

// Registry of all migrations
export const migrations: IMigration[] = [];
```

