const migration: IMigration = {
  name: '001-add-user-roles',

  up: async () => {
    await connectToDatabase();

    // Add 'role' field to all existing users with default value 'user'
    await User.updateMany(
      { role: { $exists: false } },
      { $set: { role: 'user' } }
    );

