// /lib/chroma/client.ts (updated)
import { ChromaClient, Collection } from 'chromadb';
import { developmentConfig } from './dev-config';
import { productionConfig } from './prod-config';

// Determine which config to use based on environment
const isDevelopment = process.env.NODE_ENV !== 'production';
const config = isDevelopment ? developmentConfig : productionConfig;

// Singleton pattern for ChromaDB client
let client: ChromaClient | null = null;

/**
 * Get or initialize the ChromaDB client
 */
export async function getChromaClient(): Promise<ChromaClient> {
  if (!client) {
    const protocol = config.useHttps ? 'https' : 'http';

    client = new ChromaClient({
      path: `${protocol}://${config.chromaHost}:${config.chromaPort}`,
      // Include API key if in production
      ...(config.apiKey ? { apiKey: config.apiKey } : {})
    });

    console.log(`Connected to ChromaDB at ${config.chromaHost}:${config.chromaPort}`);
  }
  return client;
}
```

