<a id="optimization"></a>
## 10. Performance Optimization Techniques

### Caching Strategy

Implement caching for frequently accessed embeddings:

```typescript
// /lib/chroma/cache.ts
import NodeCache from 'node-cache';

// Initialize cache with TTL of 1 hour and check period of 10 minutes
const embeddingCache = new NodeCache({
  stdTTL: 3600,
  checkperiod: 600,
});

/**
 * Get cached embedding for a content ID
 */
export function getCachedEmbedding(contentId: string): number[] | null {
  return embeddingCache.get(contentId) || null;
}

/**
 * Set embedding in cache
 */
export function setCachedEmbedding(contentId: string, embedding: number[]): void {
  embeddingCache.set(contentId, embedding);
}

/**
 * Clear cache for specific content IDs
 */
export function invalidateCache(contentIds: string[]): void {
  contentIds.forEach(id => embeddingCache.del(id));
}

/**
 * Get cached search results
 */
export function getCachedSearchResults(query: string, options: any): any[] | null {
  const cacheKey = `search:${query}:${JSON.stringify(options)}`;
  return embeddingCache.get(cacheKey) || null;
}

/**
 * Set search results in cache
 */
export function setCachedSearchResults(query: string, options: any, results: any[]): void {
  const cacheKey = `search:${query}:${JSON.stringify(options)}`;
  // Cache search results for a shorter period (5 minutes)
  embeddingCache.set(cacheKey, results, 300);
}
```

### Rate Limiting and Batching

Implement rate limiting for API calls:

```typescript
// /lib/ai/rate-limiter.ts
import { RateLimiter } from 'limiter';

// Create a rate limiter: 60 requests per minute
const openaiLimiter = new RateLimiter({
  tokensPerInterval: 60,
  interval: 'minute',
});

const anthropicLimiter = new RateLimiter({
  tokensPerInterval: 40,
  interval: 'minute',
});

/**
 * Execute a function with rate limiting
 */
export async function withRateLimit<T>(
  fn: () => Promise<T>,
  limiter: RateLimiter
): Promise<T> {
  // Wait until we're allowed to proceed
  await limiter.removeTokens(1);

  // Execute the function
  return fn();
}

/**
 * Rate-limited OpenAI API call
 */
export async function limitedOpenAICall<T>(fn: () => Promise<T>): Promise<T> {
  return withRateLimit(fn, openaiLimiter);
}

/**
 * Rate-limited Anthropic API call
 */
export async function limitedAnthropicCall<T>(fn: () => Promise<T>): Promise<T> {
  return withRateLimit(fn, anthropicLimiter);
}
```

### Dimension Reduction

For very large vector databases, consider dimension reduction:

```typescript
// Example of PCA dimension reduction (conceptual)
import * as math from 'mathjs';

/**
 * Perform PCA dimension reduction (simplified)
 */
export function reduceDimensions(vectors: number[][], targetDimensions: number): number[][] {
  // Center the data
  const mean = math.mean(vectors, 0);
  const centeredVectors = vectors.map(vec => math.subtract(vec, mean));

  // Calculate covariance matrix
  const covariance = math.multiply(
    math.transpose(centeredVectors),
    centeredVectors
  );

  // Get eigenvectors
  const eig = math.eigs(covariance);

  // Sort eigenvectors by eigenvalues and take top k
  const indices = Array.from({length: eig.values.length}, (_, i) => i)
    .sort((a, b) => eig.values[b] - eig.values[a])
    .slice(0, targetDimensions);

  const topEigenvectors = indices.map(i => eig.vectors[i]);

  // Project data onto principal components
  return centeredVectors.map(vec => 
    math.multiply(vec, math.transpose(topEigenvectors))
  );
}
```

### Indexing Strategy

Configure ChromaDB for efficient indexing:

```typescript
// Advanced collection creation with indexing options
export async function createOptimizedCollection(name: string): Promise<Collection> {
  const client = await getChromaClient();

  return await client.createCollection({
    name,
    metadata: { 
      hnsw:config: {
        M: 16,               // Number of bi-directional links
        efConstruction: 200, // Size of the dynamic list for nearest neighbors
      }
    }
  });
}
```

