// tests/components/Editor.test.tsx
import React from 'react';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import Editor from '@/components/editor/Editor';

// Mock the save function
const mockSave = vi.fn();

// Mock rich text editor component
vi.mock('@/components/editor/RichTextEditor', () => ({
  default: ({ content, onChange }: any) => (
    <div data-testid="mock-editor">
      <textarea
        data-testid="mock-editor-textarea"
        value={content}
        onChange={(e) => onChange(e.target.value)}
      />
    </div>
  ),
}));

describe('Editor Component', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it('renders the editor with initial content', () => {
    render(<Editor initialContent="Test content" onSave={mockSave} />);

    expect(screen.getByTestId('mock-editor')).toBeInTheDocument();
    expect(screen.getByTestId('mock-editor-textarea')).toHaveValue('Test content');
  });

  it('updates content when editor content changes', async () => {
    render(<Editor initialContent="Initial content" onSave={mockSave} />);

    const textarea = screen.getByTestId('mock-editor-textarea');
    fireEvent.change(textarea, { target: { value: 'Updated content' } });

    await waitFor(() => {
      expect(textarea).toHaveValue('Updated content');
    });
  });

  it('calls onSave when save button is clicked', async () => {
    render(<Editor initialContent="Test content" onSave={mockSave} />);

    // Find and click the save button
    const saveButton = screen.getByRole('button', { name: /save/i });
    fireEvent.click(saveButton);

    // Check if onSave was called with the correct content
    await waitFor(() => {
      expect(mockSave).toHaveBeenCalledTimes(1);
      expect(mockSave).toHaveBeenCalledWith('Test content');
    });
  });

  it('displays error message when save fails', async () => {
    mockSave.mockRejectedValueOnce(new Error('Failed to save'));

    render(<Editor initialContent="Test content" onSave={mockSave} />);

    const saveButton = screen.getByRole('button', { name: /save/i });
    fireEvent.click(saveButton);

    // Check if error message is displayed
    await waitFor(() => {
      expect(screen.getByText('Error: Failed to save')).toBeInTheDocument();
    });
  });
});
