import User, { UserDocument } from "../models/User"
import { hashPassword } from "@/lib/auth/password"
import { connectDB } from "../index"

export async function getUserByEmail(email: string): Promise<UserDocument | null> {
  await connectDB()
  return User.findOne({ email }).select("+password")
}

export async function getUserById(id: string): Promise<UserDocument | null> {
  await connectDB()
  return User.findById(id)
}

export async function createUser(userData: {
  name: string
  email: string
  password: string
  role?: "user" | "admin" | "therapist"
}): Promise<UserDocument> {
  await connectDB()

  const existingUser = await User.findOne({ email: userData.email })
  if (existingUser) {
    throw new Error("User already exists")
  }

  const newUser = new User(userData)
  return newUser.save()
}

export async function updateUser(
  id: string,
  updateData: Partial<UserDocument>
): Promise<UserDocument | null> {
  await connectDB()

  // Don't allow role changes through this function for security
  if (updateData.role) {
    delete updateData.role
  }

  if (updateData.password) {
    updateData.password = await hashPassword(updateData.password)
  }

  return User.findByIdAndUpdate(id, updateData, { new: true })
}

export async function updateUserRole(
  id: string,
  role: "user" | "admin" | "therapist"
): Promise<UserDocument | null> {
  await connectDB()
  return User.findByIdAndUpdate(id, { role }, { new: true })
}
