## Role-Based Access Control

Implement role-based access control for your application:

### 1. Authentication Middleware

**`/middleware.ts`** (for route protection):
```typescript
import { NextResponse } from "next/server"
import { getToken } from "next-auth/jwt"
import type { NextRequest } from "next/server"

// Routes that require authentication
const protectedRoutes = [
  "/profile",
  "/lessons",
  "/renascend",
]

// Routes that require admin access
const adminRoutes = [
  "/admin",
]

// Routes that require therapist access
const therapistRoutes = [
  "/admin/therapy",
]

export async function middleware(req: NextRequest) {
  const token = await getToken({ req, secret: process.env.NEXTAUTH_SECRET })
  const { pathname } = req.nextUrl

  // Check if the route is protected
  const isProtectedRoute = protectedRoutes.some(route => pathname.startsWith(route))

  // Check if the route requires admin access
  const isAdminRoute = adminRoutes.some(route => pathname.startsWith(route))

  // Check if the route requires therapist access
  const isTherapistRoute = therapistRoutes.some(route => pathname.startsWith(route))

  // If no token and the route is protected, redirect to sign in
  if (!token && isProtectedRoute) {
    const url = new URL("/auth/signin", req.url)
    url.searchParams.set("callbackUrl", pathname)
    return NextResponse.redirect(url)
  }

  // If not admin and the route requires admin access, redirect to home
  if (isAdminRoute && token?.role !== "admin") {
    return NextResponse.redirect(new URL("/", req.url))
  }

  // If not therapist and the route requires therapist access, redirect to home
  if (isTherapistRoute && token?.role !== "therapist" && token?.role !== "admin") {
    return NextResponse.redirect(new URL("/", req.url))
  }

  return NextResponse.next()
}

export const config = {
  matcher: [
    "/profile/:path*",
    "/lessons/:path*",
    "/renascend/:path*",
    "/admin/:path*",
  ],
}
```

### 2. Client-Side Access Control Hook

**`/lib/auth/useAuthorization.ts`**:
```typescript
"use client"

import { useSession } from "next-auth/react"
import { useRouter } from "next/navigation"
import { useEffect } from "react"

export function useAuthorization(
  requiredRole?: "admin" | "therapist" | "user"
) {
  const { data: session, status } = useSession()
  const router = useRouter()
  const isLoading = status === "loading"
  const userRole = session?.user?.role

  const isAuthorized = !requiredRole || 
    (userRole === requiredRole) || 
    (userRole === "admin") || 
    (requiredRole === "user" && userRole === "therapist")

  useEffect(() => {
    if (!isLoading && !isAuthorized) {
      router.push("/auth/unauthorized")
    }
  }, [isLoading, isAuthorized, router])

  return {
    isLoading,
    isAuthorized,
    role: userRole,
    session,
  }
}
```

