**`/lib/auth/rateLimit.ts`**:
```typescript
import { NextRequest, NextResponse } from "next/server"
import { Redis } from "@upstash/redis"

const redis = new Redis({
  url: process.env.UPSTASH_REDIS_URL || "",
  token: process.env.UPSTASH_REDIS_TOKEN || "",
})

interface RateLimitOptions {
  limit: number
  window: number // in seconds
}

export async function rateLimit(
  req: NextRequest,
  options: RateLimitOptions = { limit: 5, window: 60 }
) {
  const ip = req.ip || "anonymous"
  const key = `rate-limit:${ip}:${req.nextUrl.pathname}`

  // Get current count
  const count = await redis.get<number>(key)

  // If no count, set to 1 and expire after window
  if (!count) {
    await redis.set(key, 1, { ex: options.window })
    return null
  }

  // If count is less than limit, increment
  if (count < options.limit) {
    await redis.incr(key)
    return null
  }

  // Rate limit exceeded
  return NextResponse.json(
    { message: "Too many requests, please try again later" },
    { status: 429 }
  )
}
```

