  } catch (error) {
    console.error('Anthropic API error:', error);
    throw new Error(`Anthropic API error: ${error.message || 'Unknown error'}`);
  }
}

// Utility function for streaming responses
export async function streamMessage(
  systemPrompt: string,
  messages: AnthropicMessage[],
  options: {
    model?: string;
    temperature?: number;
    maxTokens?: number;
    onMessage?: (content: string) => void;
  } = {}
) {
  const anthropic = getAnthropicClient();
  const model = options.model || process.env.ANTHROPIC_MODEL || 'claude-3-opus-20240229';

  try {
    const stream = await anthropic.messages.create({
      model,
      system: systemPrompt,
      messages,
      temperature: options.temperature ?? 0.7,
      max_tokens: options.maxTokens ?? 1024,
      stream: true,
    });

    let fullContent = '';

    for await (const chunk of stream) {
      if (chunk.type === 'content_block_delta' && chunk.delta.text) {
        fullContent += chunk.delta.text;
        if (options.onMessage) {
          options.onMessage(chunk.delta.text);
        }
      }
    }

    return fullContent;
  } catch (error) {
    console.error('Anthropic streaming error:', error);
    throw new Error(`Anthropic streaming error: ${error.message || 'Unknown error'}`);
  }
}
