// Helper function to extract exercises from lesson content
function extractExercisesFromLesson(content: string): string[] {
  // Find the exercises section in the markdown
  const exerciseRegex = /## Exercises([\s\S]*?)(?:##|$)/i;
  const exerciseMatch = content.match(exerciseRegex);

  if (!exerciseMatch || !exerciseMatch[1]) {
    return [];
  }

  // Split into individual exercises
  const exerciseContent = exerciseMatch[1].trim();
  const exercises = exerciseContent.split(/\d+\.\s/).filter(Boolean);

  return exercises.map(ex => ex.trim());
}
