### Rate Limiting Implementation

```typescript
// Add rate limiting middleware
// lib/middleware/rateLimit.ts
import { NextRequest, NextResponse } from 'next/server';
import { Redis } from '@upstash/redis';

const redis = new Redis({
  url: process.env.UPSTASH_REDIS_URL,
  token: process.env.UPSTASH_REDIS_TOKEN,
});

export async function rateLimitMiddleware(req: NextRequest) {
  const ip = req.headers.get('x-forwarded-for') || 'unknown';
  const userId = req.headers.get('x-user-id') || 'anonymous';

  const key = `rate_limit:${userId}:${ip}`;
  const limit = process.env.NODE_ENV === 'production' ? 20 : 100; // Requests per minute

  const currentCount = await redis.get(key) || 0;

  if (currentCount >= limit) {
    return NextResponse.json({ error: 'Rate limit exceeded' }, { status: 429 });
  }

  // Increment count and set expiry
  await redis.incr(key);
  await redis.expire(key, 60); // 60 seconds

  return null; // Continue to the handler
}
