## Error Handling for AI API Calls

Robust error handling is essential for maintaining a good user experience when working with external AI APIs.

### Error Types and Handling

```typescript
// Define common error types
// lib/ai/errors.ts
export class AIError extends Error {
  constructor(message: string, public code: string, public status: number) {
    super(message);
    this.name = 'AIError';
  }
}

export class RateLimitError extends AIError {
  constructor(message = 'Rate limit exceeded') {
    super(message, 'RATE_LIMIT_EXCEEDED', 429);
  }
}

export class TokenLimitError extends AIError {
  constructor(message = 'Token limit exceeded') {
    super(message, 'TOKEN_LIMIT_EXCEEDED', 400);
  }
}

export class APIKeyError extends AIError {
  constructor(message = 'Invalid API key') {
    super(message, 'INVALID_API_KEY', 401);
  }
}

export class ContentFilterError extends AIError {
  constructor(message = 'Content filtered by AI provider') {
    super(message, 'CONTENT_FILTERED', 400);
  }
}

// Global error handler for AI calls
export function handleAIError(error: any) {
  // OpenAI specific errors
  if (error.response?.status === 429) {
    throw new RateLimitError();
  }

  if (error.response?.status === 401) {
    throw new APIKeyError();
  }

  if (error.response?.data?.error?.code === 'content_filter') {
    throw new ContentFilterError();
  }

  // Generic error
  throw new AIError(
    error.message || 'AI service error',
    error.code || 'UNKNOWN_ERROR',
    error.status || 500
  );
}
