### Frontend Implementation for Streaming

```typescript
// Client-side implementation for consuming a stream
// components/ui/AIStream.tsx
'use client';

import { useState, useEffect } from 'react';
import { Markdown } from '@/components/ui/Markdown';

export function AIStream({ apiEndpoint, prompt }) {
  const [response, setResponse] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);

  async function generateStreamingResponse() {
    setIsLoading(true);
    setResponse('');
    setError(null);

    try {
      const res = await fetch(apiEndpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ prompt, useStreaming: true }),
      });

      if (!res.ok) {
        throw new Error(`HTTP error! status: ${res.status}`);
      }

      const reader = res.body.getReader();
      const decoder = new TextDecoder();

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        const chunk = decoder.decode(value);
        setResponse(prev => prev + chunk);
      }
    } catch (err) {
      setError(err.message);
    } finally {
      setIsLoading(false);
    }
  }

  return (
    <div className="ai-stream">
      <button 
        onClick={generateStreamingResponse}
        disabled={isLoading}
        className="px-4 py-2 bg-blue-500 text-white rounded"
      >
        {isLoading ? 'Generating...' : 'Generate Response'}
      </button>

      {error && <div className="text-red-500 mt-2">{error}</div>}

      <div className="mt-4 p-4 border rounded">
        {response ? <Markdown content={response} /> : 'Response will appear here...'}
      </div>
    </div>
  );
}
