// lib/security/contentFilter.ts
export async function filterPrompt(prompt: string): Promise<{
  isAllowed: boolean;
  filteredPrompt?: string;
  reason?: string;
}> {
  // Simple content filtering implementation
  const moderationKeywords = [
    'hack', 'exploit', 'password', 'credit card',
    'social security', 'attack', 'vulnerability'
  ];

  const lowercasePrompt = prompt.toLowerCase();
  const foundKeywords = moderationKeywords.filter(
    keyword => lowercasePrompt.includes(keyword)
  );

  if (foundKeywords.length > 0) {
    return {
      isAllowed: false,
      reason: `Prompt contains prohibited content: ${foundKeywords.join(', ')}`
    };
  }

  return {
    isAllowed: true,
    filteredPrompt: prompt
  };
}
