  limits: {
    dailyQuota: 100, // Lower limits to control costs
    rateLimit: 10,
  },
  debug: false,
};

// Get configuration based on environment
export function getAIConfig(): AIConfig {
  return process.env.NODE_ENV === 'production'
    ? productionConfig
    : developmentConfig;
}
```

### Debug Mode for Development

Implement debug utilities for development:

```typescript
// lib/ai/debug.ts
export function logAIRequest(
  provider: 'openai' | 'anthropic',
  request: Record<string, any>
) {
  if (process.env.NODE_ENV !== 'production') {
    console.log(`[${provider.toUpperCase()} REQUEST]`, JSON.stringify(request, null, 2));
  }
}

export function logAIResponse(
  provider: 'openai' | 'anthropic',
  response: Record<string, any>
) {
  if (process.env.NODE_ENV !== 'production') {
    // Remove potentially large content from logs
    const sanitizedResponse = { ...response };
    if (sanitizedResponse.choices) {
      sanitizedResponse.choices = sanitizedResponse.choices.map(choice => ({
        ...choice,
        message: {
          ...choice.message,
          content: `${choice.message.content.substring(0, 100)}... [truncated]`,
        },
      }));
    }

    console.log(`[${provider.toUpperCase()} RESPONSE]`, JSON.stringify(sanitizedResponse, null, 2));
  }
}
```

### Feature Flags

Use feature flags to enable/disable AI features:

```typescript
// lib/config/features.ts
type FeatureFlags = {
  aiLessonGeneration: boolean;
  aiFeedback: boolean;
  renascendFeature: boolean;
  streamingResponses: boolean;
};

export const FEATURES: FeatureFlags = {
  aiLessonGeneration: true,
  aiFeedback: true,
  renascendFeature: process.env.ENABLE_RENASCEND === 'true',
  streamingResponses: process.env.ENABLE_STREAMING === 'true',
};

export function isFeatureEnabled(feature: keyof FeatureFlags): boolean {
  return FEATURES[feature] === true;
}
```

### Monitoring and Alerts

Add monitoring for production:

```typescript
// lib/monitoring/ai.ts
import { sendAlert } from '@/lib/notifications';

const COST_THRESHOLDS = {
  WARNING: 100, // $100 daily
  CRITICAL: 500, // $500 daily
};

export async function trackDailyCosts(costs: {
  openai: number;
  anthropic: number;
}) {
  const totalCost = costs.openai + costs.anthropic;

  // Only alert in production
  if (process.env.NODE_ENV !== 'production') {
    return;
  }

  if (totalCost >= COST_THRESHOLDS.CRITICAL) {
    await sendAlert({
      level: 'critical',
      message: `CRITICAL: AI costs have exceeded $${COST_THRESHOLDS.CRITICAL} today!`,
      details: costs,
    });
  } else if (totalCost >= COST_THRESHOLDS.WARNING) {
    await sendAlert({
      level: 'warning',
      message: `WARNING: AI costs have exceeded $${COST_THRESHOLDS.WARNING} today`,
      details: costs,
    });
  }
}
```

## Conclusion

Integrating AI capabilities into your Next.js application using OpenAI and Anthropic APIs requires careful planning and implementation. By following the guidelines and code examples in this guide, you can create robust, efficient, and secure AI features that enhance user experience.

Remember to:

