# Next.js API Routes Implementation Guide

## Table of Contents
1. [Introduction to Next.js API Routes](#introduction-to-nextjs-api-routes)
2. [Core API Route Implementation](#core-api-route-implementation)
3. [Blog API Routes](#blog-api-routes)
4. [GitHub Integration API Routes](#github-integration-api-routes)
5. [Notion Integration API Routes](#notion-integration-api-routes)
6. [API Security & Performance](#api-security--performance)
7. [Testing API Routes](#testing-api-routes)

## Introduction to Next.js API Routes

Next.js App Router introduces a new way to build API routes through Route Handlers, which differ significantly from the Pages Router approach. This section explains the fundamental architecture and patterns for implementing efficient API routes.

### App Router vs Pages Router

The App Router introduced in Next.js 13+ uses a file-based system with the following key differences:

```typescript
// Pages Router (pages/api/example.ts)
export default function handler(req, res) {
  res.status(200).json({ message: 'Hello from API' })
}

// App Router (app/api/example/route.ts)
import { NextResponse } from 'next/server'

export async function GET() {
  return NextResponse.json({ message: 'Hello from API' })
}
```

The App Router approach provides several benefits:
- HTTP method-specific route handlers
- Cleaner separation of concerns
- Improved TypeScript support
- Direct integration with Next.js middleware
- Better caching control

### Route Handlers Structure

In the App Router, API routes are defined in `route.ts` files within the app directory. Each HTTP method (GET, POST, PUT, DELETE, etc.) is exported as a separate function:

```typescript
// app/api/resource/route.ts
import { NextRequest, NextResponse } from 'next/server'

export async function GET(request: NextRequest) {
  // Handle GET requests
  return NextResponse.json({ data: 'get' })
}

export async function POST(request: NextRequest) {
  // Handle POST requests
  return NextResponse.json({ data: 'post' }, { status: 201 })
}

// Other methods follow the same pattern
```

## Core API Route Implementation

This section covers core patterns for implementing robust API routes including error handling, response formatting, and request validation.

### Base Structure for Route Handlers

A well-structured route handler should:
1. Validate the incoming request
2. Process the request and interact with services/data
3. Return a properly formatted response

Here's a template for creating consistent route handlers:

```typescript
// lib/api/responseUtils.ts
export interface ApiResponse<T = any> {
  success: boolean;
  data?: T;
  error?: {
    code: string;
    message: string;
    details?: any;
  };
}

export function successResponse<T>(data: T, status = 200): NextResponse<ApiResponse<T>> {
  return NextResponse.json({ success: true, data }, { status });
}

export function errorResponse(
  message: string,
  code = 'INTERNAL_ERROR',
  status = 500,
  details?: any
): NextResponse<ApiResponse> {
  return NextResponse.json(
    { success: false, error: { code, message, details } },
    { status }
  );
}
```

Using these utility functions, your route handlers become much cleaner:

```typescript
// app/api/example/route.ts
import { NextRequest } from 'next/server';
import { successResponse, errorResponse } from '@/lib/api/responseUtils';
import * as z from 'zod'; // For request validation

// Request validation schema
const createItemSchema = z.object({
  title: z.string().min(1).max(100),
  content: z.string().optional(),
});

export async function POST(request: NextRequest) {
  try {
    // Parse and validate request
    const body = await request.json();
    const validatedData = createItemSchema.parse(body);

    // Process the request (create item in database)
    // const item = await db.items.create({ data: validatedData });
    const item = { id: '123', ...validatedData };

    // Return successful response
    return successResponse(item, 201);
  } catch (error) {
    if (error instanceof z.ZodError) {
      return errorResponse('Invalid request data', 'VALIDATION_ERROR', 400, error.format());
    }

    console.error('Error processing request:', error);
    return errorResponse('An unexpected error occurred');
  }
}
```

### Error Handling Patterns

A robust error handling system is crucial for API routes. Create a middleware or wrapper function to handle common errors:

```typescript
// lib/api/errorHandler.ts
import { NextRequest, NextResponse } from 'next/server';
import { ApiResponse, errorResponse } from './responseUtils';
import { ZodError } from 'zod';
import { PrismaClientKnownRequestError } from '@prisma/client/runtime/library';

type RouteHandler = (req: NextRequest) => Promise<NextResponse<ApiResponse>>;

export function withErrorHandling(handler: RouteHandler): RouteHandler {
  return async (req: NextRequest) => {
    try {
      return await handler(req);
    } catch (error) {
      if (error instanceof ZodError) {
        return errorResponse('Validation error', 'VALIDATION_ERROR', 400, error.format());
      }

      if (error instanceof PrismaClientKnownRequestError) {
        // Handle Prisma specific errors
        if (error.code === 'P2002') {
          return errorResponse('Resource already exists', 'CONFLICT', 409);
        }
        if (error.code === 'P2025') {
          return errorResponse('Resource not found', 'NOT_FOUND', 404);
        }
      }

      console.error('Unhandled error in API route:', error);
      return errorResponse('An unexpected error occurred');
    }
  };
}
```

Apply this wrapper to your route handlers:

```typescript
export const GET = withErrorHandling(async (request) => {
  // Handler implementation without try/catch blocks
  const items = await fetchItems();
  return successResponse(items);
});
```

### Request Validation and Sanitization

Use Zod for type validation and sanitization of incoming requests:

```typescript
// lib/api/validation.ts
import { NextRequest } from 'next/server';
import { ZodSchema } from 'zod';
import { errorResponse } from './responseUtils';

export async function validateRequest<T>(
  request: NextRequest, 
  schema: ZodSchema<T>
): Promise<{ success: true; data: T } | { success: false; response: NextResponse }> {
  try {
    const body = await request.json();
    const data = schema.parse(body);
    return { success: true, data };
  } catch (error) {
    if (error instanceof Error) {
      return { 
        success: false, 
        response: errorResponse('Invalid request data', 'VALIDATION_ERROR', 400, error) 
      };
    }
    return { 
      success: false, 
      response: errorResponse('Failed to parse request') 
    };
  }
}
```

Usage in a route handler:

```typescript
export async function POST(request: NextRequest) {
  const validation = await validateRequest(request, createItemSchema);

  if (!validation.success) {
    return validation.response;
  }

  // Continue with validated data
  const data = validation.data;
  // ...
}
```

## Blog API Routes

This section covers implementing the blog-related API endpoints based on your file structure showing `/app/api/blog/route.ts`.

### Blog API Route Implementation

```typescript
// app/api/blog/route.ts
import { NextRequest } from 'next/server';
import { successResponse, errorResponse } from '@/lib/api/responseUtils';
import { withErrorHandling } from '@/lib/api/errorHandler';
import { prisma } from '@/lib/db';
import * as z from 'zod';

// Request validation schemas
const postCreateSchema = z.object({
  title: z.string().min(3).max(100),
  slug: z.string().min(3).max(100).regex(/^[a-z0-9-]+$/),
  content: z.string(),
  excerpt: z.string().max(300).optional(),
  coverImage: z.string().url().optional(),
  published: z.boolean().default(false),
  tags: z.array(z.string()).optional(),
});

const postUpdateSchema = postCreateSchema.partial();

const paginationSchema = z.object({
  page: z.coerce.number().int().positive().default(1),
  limit: z.coerce.number().int().positive().max(100).default(10),
  tag: z.string().optional(),
  search: z.string().optional(),
});

// Get all blog posts with pagination
export const GET = withErrorHandling(async (request: NextRequest) => {
  const url = new URL(request.url);

  // Parse and validate query parameters
  const params = paginationSchema.parse({
    page: url.searchParams.get('page') || 1,
    limit: url.searchParams.get('limit') || 10,
    tag: url.searchParams.get('tag'),
    search: url.searchParams.get('search'),
  });

  // Build query filters
  const where: any = { published: true };

  if (params.tag) {
    where.tags = { has: params.tag };
  }

  if (params.search) {
    where.OR = [
      { title: { contains: params.search, mode: 'insensitive' } },
      { content: { contains: params.search, mode: 'insensitive' } },
    ];
  }

  // Execute query with pagination
  const [posts, total] = await Promise.all([
    prisma.post.findMany({
      where,
      orderBy: { createdAt: 'desc' },
      skip: (params.page - 1) * params.limit,
      take: params.limit,
      select: {
        id: true,
        title: true,
        slug: true,
        excerpt: true,
        coverImage: true,
        createdAt: true,
        tags: true,
      },
    }),
    prisma.post.count({ where }),
  ]);

  // Calculate pagination metadata
  const totalPages = Math.ceil(total / params.limit);

  return successResponse({
    posts,
    meta: {
      page: params.page,
      limit: params.limit,
      total,
      totalPages,
    },
  });
});

// Create a new blog post
export const POST = withErrorHandling(async (request: NextRequest) => {
  // Authentication check (middleware would be better)
  const session = await getServerSession(); // Import from next-auth
  if (!session || !session.user.isAdmin) {
    return errorResponse('Unauthorized', 'UNAUTHORIZED', 401);
  }

  const body = await request.json();
  const data = postCreateSchema.parse(body);

  // Check if slug already exists
  const existingPost = await prisma.post.findUnique({
    where: { slug: data.slug },
  });

  if (existingPost) {
    return errorResponse('Slug already exists', 'CONFLICT', 409);
  }

  // Create new post
  const post = await prisma.post.create({
    data: {
      ...data,
      authorId: session.user.id,
    },
  });

  return successResponse(post, 201);
});
```

### Single Post Route

For operations on a single post, create a dynamic route handler:

```typescript
// app/api/blog/[slug]/route.ts
import { NextRequest } from 'next/server';
import { successResponse, errorResponse } from '@/lib/api/responseUtils';
import { withErrorHandling } from '@/lib/api/errorHandler';
import { prisma } from '@/lib/db';
import * as z from 'zod';

// Get a single blog post by slug
export const GET = withErrorHandling(async (
  request: NextRequest,
  { params }: { params: { slug: string } }
) => {
  const { slug } = params;

  const post = await prisma.post.findUnique({
    where: { slug },
    include: {
      author: {
        select: {
          id: true,
          name: true,
          image: true,
        },
      },
    },
  });

  if (!post) {
    return errorResponse('Post not found', 'NOT_FOUND', 404);
  }

  return successResponse(post);
});

// Update a blog post
export const PATCH = withErrorHandling(async (
  request: NextRequest,
  { params }: { params: { slug: string } }
) => {
  // Authentication check
  const session = await getServerSession();
  if (!session || !session.user.isAdmin) {
    return errorResponse('Unauthorized', 'UNAUTHORIZED', 401);
  }

  const { slug } = params;
  const body = await request.json();
  const data = z.object({
    title: z.string().min(3).max(100).optional(),
    content: z.string().optional(),
    excerpt: z.string().max(300).optional(),
    coverImage: z.string().url().optional(),
    published: z.boolean().optional(),
    tags: z.array(z.string()).optional(),
  }).parse(body);

  // Check if post exists
  const existingPost = await prisma.post.findUnique({
    where: { slug },
  });

  if (!existingPost) {
    return errorResponse('Post not found', 'NOT_FOUND', 404);
  }

  // Update post
  const post = await prisma.post.update({
    where: { slug },
    data,
  });

  return successResponse(post);
});

// Delete a blog post
export const DELETE = withErrorHandling(async (
  request: NextRequest,
  { params }: { params: { slug: string } }
) => {
  // Authentication check
  const session = await getServerSession();
  if (!session || !session.user.isAdmin) {
    return errorResponse('Unauthorized', 'UNAUTHORIZED', 401);
  }

  const { slug } = params;

  // Check if post exists
  const existingPost = await prisma.post.findUnique({
    where: { slug },
  });

  if (!existingPost) {
    return errorResponse('Post not found', 'NOT_FOUND', 404);
  }

  // Delete post
  await prisma.post.delete({
    where: { slug },
  });

  return successResponse({ success: true });
});
```

## GitHub Integration API Routes

This section demonstrates how to implement GitHub API integration routes based on `/app/api/github/route.ts`.

### GitHub API Route Implementation

First, create a GitHub client utility:

```typescript
// lib/github/client.ts
import { Octokit } from '@octokit/rest';

// Initialize Octokit with GitHub token
export const getGitHubClient = () => {
  const token = process.env.GITHUB_TOKEN;

  if (!token) {
    throw new Error('GITHUB_TOKEN environment variable is not set');
  }

  return new Octokit({ auth: token });
};
```

Then implement the GitHub API route:

```typescript
// app/api/github/route.ts
import { NextRequest } from 'next/server';
import { successResponse, errorResponse } from '@/lib/api/responseUtils';
import { withErrorHandling } from '@/lib/api/errorHandler';
import { getGitHubClient } from '@/lib/github/client';
import * as z from 'zod';

// Get repository information
export const GET = withErrorHandling(async (request: NextRequest) => {
  const url = new URL(request.url);
  const owner = url.searchParams.get('owner');
  const repo = url.searchParams.get('repo');

  if (!owner || !repo) {
    return errorResponse('Owner and repo parameters are required', 'BAD_REQUEST', 400);
  }

  const github = getGitHubClient();

  try {
    const [repoInfo, commits, issues] = await Promise.all([
      github.repos.get({ owner, repo }),
      github.repos.listCommits({ owner, repo, per_page: 5 }),
      github.issues.listForRepo({ owner, repo, state: 'open', per_page: 5 }),
    ]);

    return successResponse({
      repository: repoInfo.data,
      recentCommits: commits.data.map(commit => ({
        sha: commit.sha,
        message: commit.commit.message,
        author: commit.commit.author.name,
        date: commit.commit.author.date,
      })),
      openIssues: issues.data.map(issue => ({
        number: issue.number,
        title: issue.title,
        createdAt: issue.created_at,
        url: issue.html_url,
      })),
    });
  } catch (error: any) {
    if (error.status === 404) {
      return errorResponse('Repository not found', 'NOT_FOUND', 404);
    }
    throw error; // Let the error handler handle other errors
  }
});

// Create an issue in a GitHub repository
export const POST = withErrorHandling(async (request: NextRequest) => {
  // Authentication check
  const session = await getServerSession();
  if (!session) {
    return errorResponse('Unauthorized', 'UNAUTHORIZED', 401);
  }

  // Validate request body
  const schema = z.object({
    owner: z.string(),
    repo: z.string(),
    title: z.string().min(1),
    body: z.string(),
    labels: z.array(z.string()).optional(),
  });

  const body = await request.json();
  const { owner, repo, title, body: issueBody, labels } = schema.parse(body);

  const github = getGitHubClient();

  try {
    const result = await github.issues.create({
      owner,
      repo,
      title,
      body: issueBody,
      labels,
    });

    return successResponse({
      issue: {
        number: result.data.number,
        title: result.data.title,
        url: result.data.html_url,
      }
    }, 201);
  } catch (error: any) {
    if (error.status === 404) {
      return errorResponse('Repository not found', 'NOT_FOUND', 404);
    }
    throw error;
  }
});
```

### GitHub Webhook Handler

You might also want to handle GitHub webhooks:

```typescript
// app/api/github/webhook/route.ts
import { NextRequest } from 'next/server';
import { successResponse, errorResponse } from '@/lib/api/responseUtils';
import { withErrorHandling } from '@/lib/api/errorHandler';
import crypto from 'crypto';

export const POST = withErrorHandling(async (request: NextRequest) => {
  // Verify webhook signature
  const signature = request.headers.get('x-hub-signature-256');
  if (!signature) {
    return errorResponse('No signature provided', 'UNAUTHORIZED', 401);
  }

  const payload = await request.text();
  const secret = process.env.GITHUB_WEBHOOK_SECRET;

  if (!secret) {
    throw new Error('GITHUB_WEBHOOK_SECRET environment variable is not set');
  }

  const hmac = crypto.createHmac('sha256', secret);
  const digest = 'sha256=' + hmac.update(payload).digest('hex');

  if (digest !== signature) {
    return errorResponse('Invalid signature', 'UNAUTHORIZED', 401);
  }

  // Process the webhook payload
  const event = request.headers.get('x-github-event');
  const payloadJson = JSON.parse(payload);

  // Handle different event types
  switch (event) {
    case 'push':
      // Handle push event
      await handlePushEvent(payloadJson);
      break;
    case 'pull_request':
      // Handle pull request event
      await handlePullRequestEvent(payloadJson);
      break;
    // Add more event handlers as needed
  }

  return successResponse({ received: true });
});

async function handlePushEvent(payload: any) {
  // Implement push event handling logic
  console.log(`Push to ${payload.repository.full_name} by ${payload.pusher.name}`);
  // Example: update content in your database from GitHub
}

async function handlePullRequestEvent(payload: any) {
  // Implement pull request event handling logic
  console.log(`PR #${payload.number} ${payload.action}`);
  // Example: notify team of new PRs
}
```

