### Notion API Route Implementation

```typescript
// app/api/notion/route.ts
import { NextRequest } from 'next/server';
import { successResponse, errorResponse } from '@/lib/api/responseUtils';
import { withErrorHandling } from '@/lib/api/errorHandler';
import { getNotionClient } from '@/lib/notion/client';
import * as z from 'zod';

// Get database contents
export const GET = withErrorHandling(async (request: NextRequest) => {
  const url = new URL(request.url);
  const databaseId = url.searchParams.get('databaseId');

  if (!databaseId) {
    return errorResponse('Database ID is required', 'BAD_REQUEST', 400);
  }

  const notion = getNotionClient();

  try {
    // Query the database
    const response = await notion.databases.query({
      database_id: databaseId,
      sorts: [{ timestamp: 'created_time', direction: 'descending' }],
    });

    // Transform Notion response to a more usable format
    const items = response.results.map(page => {
      const properties: Record<string, any> = {};

      // Process each property
      Object.entries(page.properties).forEach(([key, value]) => {
        // Handle different property types
        switch (value.type) {
          case 'title':
            properties[key] = value.title.map(t => t.plain_text).join('');
            break;
          case 'rich_text':
            properties[key] = value.rich_text.map(t => t.plain_text).join('');
            break;
          case 'select':
            properties[key] = value.select?.name;
            break;
          case 'multi_select':
            properties[key] = value.multi_select.map(s => s.name);
            break;
          case 'date':
            properties[key] = value.date;
            break;
          case 'checkbox':
            properties[key] = value.checkbox;
            break;
          case 'url':
            properties[key] = value.url;
            break;
          // Add more property types as needed
        }
      });

      return {
        id: page.id,
        createdTime: page.created_time,
        lastEditedTime: page.last_edited_time,
        properties,
      };
    });

    return successResponse({ items });
  } catch (error: any) {
    if (error.code === 'object_not_found') {
      return errorResponse('Database not found', 'NOT_FOUND', 404);
    }
    throw error;
  }
