### Notion Page Content Handler

For retrieving and updating page content:

```typescript
// app/api/notion/page/[id]/route.ts
import { NextRequest } from 'next/server';
import { successResponse, errorResponse } from '@/lib/api/responseUtils';
import { withErrorHandling } from '@/lib/api/errorHandler';
import { getNotionClient } from '@/lib/notion/client';

// Get page content
export const GET = withErrorHandling(async (
  request: NextRequest,
  { params }: { params: { id: string } }
) => {
  const { id } = params;
  const notion = getNotionClient();

  try {
    // Get page blocks
    const blocks = await notion.blocks.children.list({
      block_id: id,
    });

    // Get page metadata
    const page = await notion.pages.retrieve({
      page_id: id,
    });

    return successResponse({
      page,
      blocks: blocks.results,
    });
  } catch (error: any) {
    if (error.code === 'object_not_found') {
      return errorResponse('Page not found', 'NOT_FOUND', 404);
    }
    throw error;
  }
});

// Update page content
export const PATCH = withErrorHandling(async (
  request: NextRequest,
  { params }: { params: { id: string } }
) => {
  // Authentication check
  const session = await getServerSession();
  if (!session) {
    return errorResponse('Unauthorized', 'UNAUTHORIZED', 401);
  }

  const { id } = params;
  const notion = getNotionClient();

  const { properties, content } = await request.json();

  try {
    // Update page properties
    if (properties) {
      await notion.pages.update({
        page_id: id,
        properties,
      });
    }

    // Update page content blocks
    if (content) {
      // First get existing blocks
      const blocks = await notion.blocks.children.list({
        block_id: id,
      });

      // Delete existing blocks
      for (const block of blocks.results) {
        await notion.blocks.delete({
          block_id: block.id,
        });
      }

      // Add new blocks
      await notion.blocks.children.append({
        block_id: id,
        children: content,
      });
    }

    return successResponse({ success: true });
  } catch (error: any) {
    if (error.code === 'object_not_found') {
      return errorResponse('Page not found', 'NOT_FOUND', 404);
    }
    throw error;
  }
});
