## API Security & Performance

This section covers implementing security and performance measures for your API routes.

### Rate Limiting

Implement rate limiting to protect your API from abuse:

```typescript
// lib/api/rateLimit.ts
import { NextRequest, NextResponse } from 'next/server';
import { Redis } from '@upstash/redis';
import { Ratelimit } from '@upstash/ratelimit';

// Initialize Redis client
const redis = new Redis({
  url: process.env.UPSTASH_REDIS_URL || '',
  token: process.env.UPSTASH_REDIS_TOKEN || '',
});

// Create a rate limiter instance
const limiter = new Ratelimit({
  redis,
  limiter: Ratelimit.slidingWindow(20, '1m'), // 20 requests per minute
  analytics: true,
});

export async function rateLimit(
  request: NextRequest,
  identifier?: string
): Promise<{ success: boolean; limit?: number; remaining?: number; reset?: number }> {
  // Determine the rate limit key
  const ip = request.ip || 'anonymous';
  const key = identifier || ip;

  // Check rate limit
  const result = await limiter.limit(key);

  return {
    success: result.success,
    limit: result.limit,
    remaining: result.remaining,
    reset: result.reset,
  };
}

// Create a middleware to apply rate limiting
export function withRateLimit(handler: Function) {
  return async (request: NextRequest, ...args: any[]) => {
    const result = await rateLimit(request);

    if (!result.success) {
      return NextResponse.json(
        {
          success: false,
          error: {
            code: 'RATE_LIMIT_EXCEEDED',
            message: 'Too many requests, please try again later',
          },
        },
        {
          status: 429,
          headers: {
            'X-RateLimit-Limit': result.limit?.toString() || '',
            'X-RateLimit-Remaining': result.remaining?.toString() || '0',
            'X-RateLimit-Reset': result.reset?.toString() || '',
          },
        }
      );
    }

    const response = await handler(request, ...args);

    // Add rate limit headers to response
    response.headers.set('X-RateLimit-Limit', result.limit?.toString() || '');
    response.headers.set('X-RateLimit-Remaining', result.remaining?.toString() || '');
    response.headers.set('X-RateLimit-Reset', result.reset?.toString() || '');

    return response;
  };
}
```

