### Creating API Middleware

Create reusable middleware for common API functionalities:

```typescript
// lib/api/middleware.ts
import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { errorResponse } from './responseUtils';

// Authentication middleware
export function withAuth(handler: Function, options?: { adminOnly?: boolean }) {
  return async (request: NextRequest, ...args: any[]) => {
    const session = await getServerSession();

    if (!session) {
      return errorResponse('Unauthorized', 'UNAUTHORIZED', 401);
    }

    if (options?.adminOnly && !session.user.isAdmin) {
      return errorResponse('Forbidden', 'FORBIDDEN', 403);
    }

    // Add session to request for use in handler
    const requestWithSession = Object.assign(request, { session });

    return handler(requestWithSession, ...args);
  };
}

// Logging middleware
export function withLogging(handler: Function) {
  return async (request: NextRequest, ...args: any[]) => {
    const start = Date.now();
    const method = request.method;
    const url = request.url;

    console.log(`API Request: ${method} ${url}`);

    try {
      const response = await handler(request, ...args);

      const duration = Date.now() - start;
      const status = response.status;

      console.log(`API Response: ${method} ${url} ${status} - ${duration}ms`);

      return response;
    } catch (error) {
      const duration = Date.now() - start;

      console.error(`API Error: ${method} ${url} - ${duration}ms`, error);

      throw error;
    }
  };
}

// Combining middlewares
export function withMiddleware(handler: Function, middlewares: Function[]) {
  return middlewares.reduceRight((next, middleware) => {
    return middleware(next);
  }, handler);
}
