Create a version selection middleware:

```typescript
// lib/api/versioning.ts
import { NextRequest, NextResponse } from 'next/server';

export function selectApiVersion(request: NextRequest) {
  // Get requested version from header or default to latest
  const requestedVersion = request.headers.get('x-api-version') || 'latest';

  // Map of available versions
  const versions = {
    'v1': '/api/v1',
    'v2': '/api/v2',
    'latest': '/api/v2', // Set your latest version here
  };

  // Get the version path prefix
  const versionPath = versions[requestedVersion as keyof typeof versions] || versions.latest;

  // Rewrite the URL to include the version
  const url = request.nextUrl.clone();
  const path = url.pathname;

  // Skip if path already includes version
  if (path.includes('/v1/') || path.includes('/v2/')) {
    return NextResponse.next();
  }

  // Replace /api/ with version path
  const newPath = path.replace('/api/', `${versionPath}/`);
  url.pathname = newPath;

  return NextResponse.rewrite(url);
}
```

