## Advanced Features

### Image Uploads

Let's implement image uploads by creating a custom component:

```tsx
// components/editor/extensions/ImageUpload.ts
import { Extension } from '@tiptap/core';
import Image from '@tiptap/extension-image';

// Create a custom extension that extends the Image extension
export const ImageUpload = Image.extend({
  addCommands() {
    return {
      ...this.parent?.(),
      // Add a custom command to handle image uploads
      uploadImage: (file: File) => ({ commands }) => {
        if (!file) return false;

        // Create a URL for the file
        const url = URL.createObjectURL(file);

        // Insert the image
        return commands.setImage({ src: url, alt: file.name });
      },
    };
  },
});

// Create an interface for the image upload function
export interface ImageUploadOptions {
  uploadFn: (file: File) => Promise<string>;
}

// Create an extension to handle image uploads
export const ImageUploadExtension = Extension.create<ImageUploadOptions>({
  name: 'imageUpload',

  addStorage() {
    return {
      uploadFn: this.options.uploadFn,
    };
  },

  addCommands() {
    return {
      uploadImageFromFile: (file: File) => ({ editor }) => {
        const { uploadFn } = this.storage;

        if (!file) return false;

        // Show a loading state if needed
        // Insert a temporary image
        editor.commands.setImage({ src: URL.createObjectURL(file), alt: 'Uploading...' });

        // Upload the image
        uploadFn(file)
          .then((url) => {
            // Replace the temporary image with the uploaded one
            // You need to find the right node to replace
            // This is simplified and may need adjustments
            editor.commands.setImage({ src: url, alt: file.name });
          })
          .catch((error) => {
            console.error('Failed to upload image:', error);
            // Handle error state
          });

        return true;
      },
    };
  },
});
```

