### Callout Extension

```tsx
// components/editor/extensions/CalloutExtension.ts
import { Node, mergeAttributes } from '@tiptap/core';

export interface CalloutOptions {
  HTMLAttributes: Record<string, any>;
}

// Create a custom callout node
export const Callout = Node.create<CalloutOptions>({
  name: 'callout',

  group: 'block',

  content: 'inline*',

  defining: true,

  addAttributes() {
    return {
      type: {
        default: 'info',
        rendered: true,
      },
    };
  },

  parseHTML() {
    return [
      {
        tag: 'div[data-type="callout"]',
      },
    ];
  },

  renderHTML({ HTMLAttributes }) {
    const type = HTMLAttributes.type || 'info';
    const classes = {
      info: 'bg-blue-50 border-l-4 border-blue-500 text-blue-700 p-4',
      warning: 'bg-yellow-50 border-l-4 border-yellow-500 text-yellow-700 p-4',
      error: 'bg-red-50 border-l-4 border-red-500 text-red-700 p-4',
      success: 'bg-green-50 border-l-4 border-green-500 text-green-700 p-4',
    }[type] || 'bg-blue-50 border-l-4 border-blue-500 text-blue-700 p-4';

    return ['div', mergeAttributes(HTMLAttributes, {
      'data-type': 'callout',
      class: classes,
    }), 0];
  },

  addCommands() {
    return {
      setCallout: (attributes) => ({ commands }) => {
        return commands.setNode(this.name, attributes);
      },
      toggleCallout: (attributes) => ({ commands }) => {
        return commands.toggleNode(this.name, 'paragraph', attributes);
      },
    };
  },
});
```

