## Data Persistence with MongoDB

Let's create a service to save and load TipTap content to/from MongoDB:

```typescript
// lib/db/services/contentService.ts
import { connectToDatabase } from '../index';
import { Post, Lesson } from '../models';
import mongoose from 'mongoose';

interface ContentServiceOptions {
  contentType: 'post' | 'lesson';
}

export class ContentService {
  private contentType: 'post' | 'lesson';
  private model: typeof Post | typeof Lesson;

  constructor(options: ContentServiceOptions) {
    this.contentType = options.contentType;
    this.model = this.contentType === 'post' ? Post : Lesson;
  }

  // Save content
  async saveContent(id: string, content: string, metadata: any = {}) {
    await connectToDatabase();

    const isValidId = mongoose.Types.ObjectId.isValid(id);

    if (isValidId) {
      // Update existing document
      const result = await this.model.findByIdAndUpdate(
        id,
        { 
          content,
          lastModified: new Date(),
          ...metadata,
        },
        { new: true }
      );

      return result;
    } else {
      // Create a new document
      const newDoc = new this.model({
        content,
        createdAt: new Date(),
        lastModified: new Date(),
        ...metadata,
      });

      const result = await newDoc.save();
      return result;
    }
  }

  // Load content
  async loadContent(id: string) {
    await connectToDatabase();

    if (!mongoose.Types.ObjectId.isValid(id)) {
      throw new Error('Invalid ID format');
    }

    const document = await this.model.findById(id);

    if (!document) {
      throw new Error('Document not found');
    }

    return {
      content: document.content,
      metadata: {
        createdAt: document.createdAt,
        lastModified: document.lastModified,
        ...document.toObject(),
      },
    };
  }

  // Get all content items (for listing)
  async getAllContent() {
    await connectToDatabase();

    const documents = await this.model.find({})
      .sort({ lastModified: -1 })
      .select('title slug content createdAt lastModified');

    return documents;
  }
}

// Create and export instances for posts and lessons
export const postService = new ContentService({ contentType: 'post' });
export const lessonService = new ContentService({ contentType: 'lesson' });
```

Create API routes to save and load content:

```typescript
// app/api/content/[type]/[id]/route.ts
import { NextRequest, NextResponse } from 'next/server';
import { postService, lessonService } from '@/lib/db/services/contentService';

// Helper to get the right service
const getService = (type: string) => {
  return type === 'post' ? postService : lessonService;
};

// GET handler to load content
export async function GET(
  request: NextRequest,
  { params }: { params: { type: string; id: string } }
) {
  try {
    const service = getService(params.type);
    const data = await service.loadContent(params.id);

    return NextResponse.json({ success: true, data });
  } catch (error: any) {
    return NextResponse.json(
      { success: false, error: error.message },
      { status: 400 }
    );
  }
}

// POST handler to save content
export async function POST(
  request: NextRequest,
  { params }: { params: { type: string; id: string } }
) {
  try {
    const service = getService(params.type);
    const body = await request.json();

    const { content, ...metadata } = body;

    if (!content) {
      return NextResponse.json(
        { success: false, error: 'Content is required' },
        { status: 400 }
      );
    }

    const result = await service.saveContent(params.id, content, metadata);

    return NextResponse.json({ success: true, data: result });
  } catch (error: any) {
    return NextResponse.json(
      { success: false, error: error.message },
      { status: 400 }
    );
  }
}
