## Content Versioning and Draft System

Let's implement a simple versioning system:

```typescript
// lib/db/models/ContentVersion.ts
import mongoose from 'mongoose';

// Define the schema for content versions
const ContentVersionSchema = new mongoose.Schema({
  contentId: {
    type: mongoose.Schema.Types.ObjectId,
    required: true,
    refPath: 'contentType',
  },
  contentType: {
    type: String,
    required: true,
    enum: ['Post', 'Lesson'],
  },
  version: {
    type: Number,
    required: true,
  },
  content: {
    type: String,
    required: true,
  },
  createdAt: {
    type: Date,
    default: Date.now,
  },
  createdBy: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'User',
  },
  comment: {
    type: String,
  },
});

// Create indices for better query performance
ContentVersionSchema.index({ contentId: 1, version: -1 });

export const ContentVersion = mongoose.models.ContentVersion || 
  mongoose.model('ContentVersion', ContentVersionSchema);
```

