// Save a draft
async saveDraft(contentId: string | null, content: string, userId?: string, metadata: any = {}) {
  await connectToDatabase();

  // If contentId is provided, validate it
  if (contentId && !mongoose.Types.ObjectId.isValid(contentId)) {
    throw new Error('Invalid ID format');
  }

  // Look for an existing draft
  const query = {
    ...(contentId ? { contentId } : {}),
