    createdBy: userId,
    status: 'draft',
  };

  const existingDraft = await Draft.findOne(query);

  if (existingDraft) {
    // Update existing draft
    existingDraft.content = content;
    existingDraft.updatedAt = new Date();
    existingDraft.metadata = { ...existingDraft.metadata, ...metadata };

    await existingDraft.save();
    return existingDraft;
  } else {
    // Create a new draft
    const newDraft = new Draft({
      contentId,
      contentType: this.contentType === 'post' ? 'Post' : 'Lesson',
      content,
      createdAt: new Date(),
      updatedAt: new Date(),
      createdBy: userId,
      status: 'draft',
      metadata,
    });

    await newDraft.save();
    return newDraft;
  }
}

