  if (!mongoose.Types.ObjectId.isValid(draftId)) {
    throw new Error('Invalid draft ID format');
  }

  const draft = await Draft.findById(draftId);

  if (!draft) {
    throw new Error('Draft not found');
  }

  return draft;
}

// Publish a draft (convert to actual content)
async publishDraft(draftId: string, userId?: string) {
  await connectToDatabase();

  const draft = await this.getDraft(draftId);

  // If this is updating existing content
  if (draft.contentId) {
    // Save the content
    const result = await this.saveContent(
      draft.contentId.toString(), 
      draft.content,
      draft.metadata
    );

    // Create a version
    await this.createVersion(
      draft.contentId.toString(),
      draft.content,
      userId,
      'Published from draft'
    );

    // Delete the draft or mark as published
    await Draft.findByIdAndDelete(draftId);

    return result;
  } else {
    // Create new content
    const newContent = new this.model({
      content: draft.content,
      createdAt: new Date(),
      lastModified: new Date(),
      ...draft.metadata,
    });

    const result = await newContent.save();

    // Create initial version
    await this.createVersion(
      result._id.toString(),
      draft.content,
      userId,
      'Initial version from draft'
    );

    // Delete the draft
    await Draft.findByIdAndDelete(draftId);

    return result;
  }
}
