## Collaborative Editing

To implement collaborative editing with TipTap, we'll use Y.js and WebSockets. First, install the necessary packages:

```bash
npm install @tiptap/extension-collaboration @tiptap/extension-collaboration-cursor y-websocket yjs
```

Create a collaborative editor component:

```tsx
// components/editor/CollaborativeEditor.tsx
import { useEditor, EditorContent } from '@tiptap/react';
import StarterKit from '@tiptap/starter-kit';
import Collaboration from '@tiptap/extension-collaboration';
import CollaborationCursor from '@tiptap/extension-collaboration-cursor';
import { WebsocketProvider } from 'y-websocket';
import * as Y from 'yjs';
import { useEffect, useState } from 'react';
import MenuBar from './MenuBar';

interface CollaborativeEditorProps {
  documentId: string;
  username: string;
  userColor?: string;
  onChange?: (html: string) => void;
  editable?: boolean;
}

export default function CollaborativeEditor({
  documentId,
  username,
  userColor = '#' + Math.floor(Math.random() * 16777215).toString(16), // Random color
  onChange = () => {},
  editable = true,
}: CollaborativeEditorProps) {
  const [isMounted, setIsMounted] = useState(false);
  const [provider, setProvider] = useState<WebsocketProvider | null>(null);

  // Initialize Yjs document and provider on client-side
  useEffect(() => {
    if (typeof window !== 'undefined') {
      // Create a new Yjs document
      const ydoc = new Y.Doc();

      // Connect to WebSocket server
      // Replace with your actual WebSocket server URL
      const websocketProvider = new WebsocketProvider(
        'wss://your-websocket-server.com',
        `document-${documentId}`,
        ydoc
      );

      websocketProvider.awareness.setLocalStateField('user', {
        name: username,
        color: userColor,
      });

      setProvider(websocketProvider);

      return () => {
        // Clean up connections when component unmounts
        ydoc.destroy();
        websocketProvider.destroy();
      };
    }
  }, [documentId, username, userColor]);

  // Initialize the editor
  const editor = useEditor({
    extensions: [
      StarterKit.configure({
        // Disable history as it's handled by Collaboration
        history: false,
      }),
      // Set up collaboration
      Collaboration.configure({
        document: provider?.doc,
      }),
      // Set up collaboration cursors
      CollaborationCursor.configure({
        provider: provider,
      }),
    ],
    editable,
    onUpdate: ({ editor }) => {
      // Call the onChange callback with new content
      onChange(editor.getHTML());
    },
  }, [provider]);

  // Handle client-side mounting to avoid hydration issues
  useEffect(() => {
    setIsMounted(true);
  }, []);

  // Don't render the editor on the server
  if (!isMounted) {
    return null;
  }

  return (
    <div className="editor-container">
      {editor && editable && <MenuBar editor={editor} />}
      <div className="collaborative-status">
        {provider?.awareness.getStates().size} user(s) online
      </div>
      <EditorContent editor={editor} className="prose max-w-none" />
    </div>
  );
}
```

Create a simple WebSocket server for collaboration:

```typescript
// server/websocket.ts
import { WebSocketServer } from 'ws';
import http from 'http';
import { setupWSConnection } from 'y-websocket/bin/utils';

export function setupWebSocketServer(server: http.Server) {
  const wss = new WebSocketServer({ server });

  wss.on('connection', (ws, req) => {
    setupWSConnection(ws, req);

    ws.on('error', console.error);
  });

  console.log('WebSocket server is running');

  return wss;
}
```

Update your Next.js server setup to include the WebSocket server:

```typescript
// server.js (or wherever your custom server is defined)
import { createServer } from 'http';
import next from 'next';
import { setupWebSocketServer } from './server/websocket';

const dev = process.env.NODE_ENV !== 'production';
const app = next({ dev });
const handle = app.getRequestHandler();

app.prepare().then(() => {
  const server = createServer((req, res) => {
    handle(req, res);
  });

  // Set up WebSocket server
  setupWebSocketServer(server);

  server.listen(3000, () => {
    console.log('> Ready on http://localhost:3000');
  });
});
