import MobileMenuBar from './MobileMenuBar';
import ImageUploadButton from './ImageUploadButton';
import TableButtons from './TableButtons';
import CalloutButtons from './CalloutButtons';

interface CompleteEditorProps {
  initialContent?: string;
  placeholder?: string;
  onChange?: (html: string) => void;
  onSave?: (html: string) => void;
  editable?: boolean;
  uploadImage?: (file: File) => Promise<string>;
  ariaLabel?: string;
}

export default function CompleteEditor({
  initialContent = '<p></p>',
  placeholder = 'Start writing...',
  onChange = () => {},
  onSave = () => {},
  editable = true,
  uploadImage = async (file) => URL.createObjectURL(file),
  ariaLabel = 'Rich text editor',
}: CompleteEditorProps) {
  const [isMounted, setIsMounted] = useState(false);

  // Initialize the editor
  const editor = useEditor({
    extensions: [
      StarterKit.configure({
        heading: {
          levels: [1, 2, 3, 4, 5, 6],
        },
      }),
      Placeholder.configure({
        placeholder,
      }),
      Link.configure({
        openOnClick: false,
        HTMLAttributes: {
          class: 'text-blue-500 underline',
        },
      }),
      Image.configure({
        HTMLAttributes: {
          class: 'max-w-full h-auto my-4 rounded',
        },
      }),
      ...TableExtensions,
      CodeBlockExtension,
      Callout,
    ],
    content: initialContent,
    editable,
    onUpdate: ({ editor }) => {
      onChange(editor.getHTML());
    },
  });

  // Handle client-side mounting to avoid hydration issues
  useEffect(() => {
    setIsMounted(true);
  }, []);

  // Auto-save functionality
  useEffect(() => {
    if (!editor || !onSave) return;

    const interval = setInterval(() => {
      onSave(editor.getHTML());
    }, 60000); // Save every minute

    return () => clearInterval(interval);
  }, [editor, onSave]);

  // Handle keyboard shortcuts
  useEffect(() => {
    if (!editor) return;

    // Save on Ctrl+S
    const handleKeyDown = (event: KeyboardEvent) => {
      if ((event.ctrlKey || event.metaKey) && event.key === 's') {
        event.preventDefault();
        onSave(editor.getHTML());
      }
    };

    window.addEventListener('keydown', handleKeyDown);

    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [editor, onSave]);

  // Don't render the editor on the server
  if (!isMounted) {
    return null;
  }

  return (
    <div className="editor-container">
      {editor && editable && (
        <>
          <div className="hidden md:block">
            <MenuBar editor={editor} />
            <div className="flex gap-2 p-2 border-b border-gray-200 bg-gray-50">
              <ImageUploadButton editor={editor} />
              <TableButtons editor={editor} />
              <CalloutButtons editor={editor} />
            </div>
          </div>
          <div className="md:hidden">
            <MobileMenuBar editor={editor} />
          </div>
        </>
      )}

      <EditorContent 
        editor={editor} 
        className="prose max-w-none"
        aria-label={ariaLabel}
      />

      {editable && (
        <div className="flex justify-between items-center p-2 border-t border-gray-200 bg-gray-50">
          <button
            onClick={() => onSave(editor?.getHTML() || '')}
            className="px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600"
          >
            Save
          </button>

