```

### Creating the Database Connection Client

Create the file `lib/db/index.ts`:

```typescript
import { MongoClient, Db } from 'mongodb';

// Global variable to cache the database connection
let cachedClient: MongoClient | null = null;
let cachedDb: Db | null = null;

/**
 * Connects to MongoDB and returns the database instance
 * Uses connection pooling through a cached connection
 */
export async function connectToDatabase(): Promise<{ client: MongoClient; db: Db }> {
  // If we have a cached connection, return it
  if (cachedClient && cachedDb) {
    return { client: cachedClient, db: cachedDb };
  }

  // Check if we have the required environment variables
  if (!process.env.MONGODB_URI || !process.env.MONGODB_DB_NAME) {
    throw new Error('MongoDB connection string or database name not provided');
  }

  // Set up connection options with a reasonable pool size
  const options = {
    maxPoolSize: 10, // Keep up to 10 socket connections
    minPoolSize: 1   // Maintain at least one connection
  };

  try {
    // Connect to the MongoDB server
    const client = await MongoClient.connect(process.env.MONGODB_URI, options);

    // Get database reference
    const db = client.db(process.env.MONGODB_DB_NAME);

    // Cache the client and database connection
    cachedClient = client;
    cachedDb = db;

    return { client, db };
  } catch (error) {
    console.error('MongoDB connection error:', error);
    throw new Error('Failed to connect to database');
  }
}

/**
 * Get a reference to a specific collection
 * @param collectionName The name of the collection
 */
export async function getCollection(collectionName: string) {
  const { db } = await connectToDatabase();
  return db.collection(collectionName);
}

/**
 * Gracefully close database connection
 * Important for proper cleanup during application shutdown
 */
export async function closeDatabaseConnection(): Promise<void> {
  if (cachedClient) {
    await cachedClient.close();
    cachedClient = null;
    cachedDb = null;
  }
}
```

