```typescript
import { z } from 'zod';
import { ObjectId } from 'mongodb';
import { getCollection } from '../index';
import type { User, UserCreateInput, UserUpdateInput } from '../../../types/user';

// Collection name
const COLLECTION = 'users';

// Zod schema for validation
export const UserSchema = z.object({
  email: z.string().email(),
  name: z.string().min(2),
  role: z.enum(['user', 'admin']),
  passwordHash: z.string(),
  createdAt: z.date(),
  updatedAt: z.date()
});

// Helper functions
export const UserModel = {
  /**
   * Create a new user
   */
  async create(userData: UserCreateInput): Promise<User> {
    const now = new Date();
    const user: User = {
      ...userData,
      createdAt: now,
      updatedAt: now
    };

    // Validate with Zod
    UserSchema.parse(user);

    const collection = await getCollection(COLLECTION);
    const result = await collection.insertOne(user);

    return { ...user, _id: result.insertedId };
  },

  /**
   * Find a user by ID
   */
  async findById(id: string | ObjectId): Promise<User | null> {
    const collection = await getCollection(COLLECTION);
    const objectId = typeof id === 'string' ? new ObjectId(id) : id;
    return collection.findOne<User>({ _id: objectId });
  },

  /**
   * Find a user by email
   */
  async findByEmail(email: string): Promise<User | null> {
    const collection = await getCollection(COLLECTION);
    return collection.findOne<User>({ email });
  },

  /**
   * Update a user
   */
  async update(id: string | ObjectId, userData: UserUpdateInput): Promise<User | null> {
    const objectId = typeof id === 'string' ? new ObjectId(id) : id;
    const collection = await getCollection(COLLECTION);

    const updateData = {
      ...userData,
      updatedAt: new Date()
    };

    await collection.updateOne(
      { _id: objectId },
      { $set: updateData }
    );

    return this.findById(objectId);
  },

  /**
   * Delete a user
   */
  async delete(id: string | ObjectId): Promise<boolean> {
    const objectId = typeof id === 'string' ? new ObjectId(id) : id;
    const collection = await getCollection(COLLECTION);
    const result = await collection.deleteOne({ _id: objectId });
    return result.deletedCount === 1;
  }
};
```

