import { z } from 'zod';
import { ObjectId } from 'mongodb';
import { getCollection } from '../index';
import type { Lesson, LessonCreateInput, LessonUpdateInput } from '../../../types/lesson';

// Collection name
const COLLECTION = 'lessons';

// Zod schema for validation
export const LessonSchema = z.object({
  title: z.string().min(3),
  description: z.string(),
  content: z.string(),
  category: z.string(),
  tags: z.array(z.string()),
  authorId: z.instanceof(ObjectId),
  published: z.boolean(),
  createdAt: z.date(),
  updatedAt: z.date()
});

// Helper functions
export const LessonModel = {
  /**
   * Create a new lesson
   */
  async create(lessonData: LessonCreateInput): Promise<Lesson> {
    const now = new Date();
    const lesson: Lesson = {
      ...lessonData,
      createdAt: now,
      updatedAt: now
    };

    // Validate with Zod
    LessonSchema.parse(lesson);

    const collection = await getCollection(COLLECTION);
    const result = await collection.insertOne(lesson);

    return { ...lesson, _id: result.insertedId };
  },

  /**
   * Find a lesson by ID
   */
  async findById(id: string | ObjectId): Promise<Lesson | null> {
    const collection = await getCollection(COLLECTION);
    const objectId = typeof id === 'string' ? new ObjectId(id) : id;
    return collection.findOne<Lesson>({ _id: objectId });
  },

  /**
   * Find lessons with pagination
   */
  async findMany(options: {
    published?: boolean;
    category?: string;
    tags?: string[];
    authorId?: string | ObjectId;
    limit?: number;
    skip?: number;
  }): Promise<Lesson[]> {
    const { published, category, tags, authorId, limit = 10, skip = 0 } = options;

    const query: Record<string, any> = {};

    if (published !== undefined) {
      query.published = published;
    }

    if (category) {
      query.category = category;
    }

    if (tags && tags.length > 0) {
      query.tags = { $in: tags };
    }

    if (authorId) {
      query.authorId = typeof authorId === 'string' ? new ObjectId(authorId) : authorId;
    }

    const collection = await getCollection(COLLECTION);
    return collection
      .find<Lesson>(query)
      .sort({ createdAt: -1 })
      .skip(skip)
      .limit(limit)
      .toArray();
  },

  /**
   * Update a lesson
   */
  async update(id: string | ObjectId, lessonData: LessonUpdateInput): Promise<Lesson | null> {
    const objectId = typeof id === 'string' ? new ObjectId(id) : id;
    const collection = await getCollection(COLLECTION);

    const updateData = {
      ...lessonData,
      updatedAt: new Date()
    };

    await collection.updateOne(
      { _id: objectId },
      { $set: updateData }
    );

    return this.findById(objectId);
  },

  /**
   * Delete a lesson
   */
  async delete(id: string | ObjectId): Promise<boolean> {
    const objectId = typeof id === 'string' ? new ObjectId(id) : id;
    const collection = await getCollection(COLLECTION);
    const result = await collection.deleteOne({ _id: objectId });
    return result.deletedCount === 1;
  }
};
