import { ObjectId } from 'mongodb';
import { UserModel } from '../models/User';
import type { UserCreateInput, UserUpdateInput } from '../../../types/user';

/**
 * User-related database queries with error handling
 */
export const userQueries = {
  /**
   * Create a new user with validation
   */
  async createUser(userData: UserCreateInput) {
    try {
      return await UserModel.create(userData);
    } catch (error) {
      console.error('Error creating user:', error);
      throw new Error('Failed to create user');
    }
  },

  /**
   * Get user by ID with proper ObjectId conversion
   */
  async getUserById(id: string) {
    try {
      if (!ObjectId.isValid(id)) {
        throw new Error('Invalid user ID format');
      }

      const user = await UserModel.findById(id);
      if (!user) {
        throw new Error('User not found');
      }

      return user;
    } catch (error) {
      console.error('Error getting user by ID:', error);
      throw error;
    }
  },

  /**
   * Get user by email with case-insensitive search
   */
  async getUserByEmail(email: string) {
    try {
      // Normalize email to lowercase for consistent lookup
      const normalizedEmail = email.toLowerCase();
      const user = await UserModel.findByEmail(normalizedEmail);

      return user;
    } catch (error) {
      console.error('Error getting user by email:', error);
      throw new Error('Failed to get user by email');
    }
  },

  /**
   * Update user with validation
   */
  async updateUser(id: string, userData: UserUpdateInput) {
    try {
      if (!ObjectId.isValid(id)) {
        throw new Error('Invalid user ID format');
      }

      const updated = await UserModel.update(id, userData);
      if (!updated) {
        throw new Error('User not found or update failed');
      }

      return updated;
    } catch (error) {
      console.error('Error updating user:', error);
      throw error;
    }
  },

  /**
   * Delete user with confirmation
   */
  async deleteUser(id: string) {
    try {
      if (!ObjectId.isValid(id)) {
        throw new Error('Invalid user ID format');
      }

      const deleted = await UserModel.delete(id);
      if (!deleted) {
        throw new Error('User not found or delete failed');
      }

      return true;
    } catch (error) {
      console.error('Error deleting user:', error);
      throw error;
    }
  }
};
