import { z, ZodError } from 'zod';
import { ObjectId } from 'mongodb';

// Custom Zod transformation for ObjectId validation
export const objectIdSchema = z.string().refine(
  (id) => ObjectId.isValid(id),
  { message: 'Invalid ObjectId format' }
