/**
 * Formats ZodError into a more user-friendly error message
 */
export function formatZodError(error: ZodError): Record<string, string> {
  const formattedErrors: Record<string, string> = {};

  error.errors.forEach((err) => {
    const path = err.path.join('.');
    formattedErrors[path] = err.message;
  });

  return formattedErrors;
}

/**
 * Validates data against a schema and returns formatted errors
 * @returns [isValid, errors]
 */
export function validateWithZod<T>(schema: z.ZodSchema<T>, data: unknown): [boolean, null | Record<string, string>] {
  try {
    schema.parse(data);
    return [true, null];
  } catch (error) {
    if (error instanceof ZodError) {
      return [false, formatZodError(error)];
    }
    throw error;
  }
}

/**
 * Safe parse with proper typing
 */
export function safeParse<T>(schema: z.ZodSchema<T>, data: unknown): { success: boolean; data?: T; errors?: Record<string, string> } {
  const result = schema.safeParse(data);

  if (result.success) {
    return { success: true, data: result.data };
  }

  return { success: false, errors: formatZodError(result.error) };
}
