import { connectToDatabase } from '../index';

interface Migration {
  version: number;
  name: string;
  up: () => Promise<void>;
  down: () => Promise<void>;
}

/**
 * Simple migration system
 */
export class MigrationRunner {
  private migrations: Migration[] = [];

  /**
   * Register a new migration
   */
  register(migration: Migration): void {
    this.migrations.push(migration);
    // Sort migrations by version
    this.migrations.sort((a, b) => a.version - b.version);
  }

  /**
   * Run all pending migrations
   */
  async runPending(): Promise<void> {
    const { db } = await connectToDatabase();

    // Create migrations collection if it doesn't exist
    if (!(await db.listCollections({ name: 'migrations' }).toArray()).length) {
      await db.createCollection('migrations');
    }

    // Get the current version
    const migrationCollection = db.collection('migrations');
    const latestMigration = await migrationCollection
      .find()
      .sort({ version: -1 })
      .limit(1)
      .toArray();

    const currentVersion = latestMigration.length ? latestMigration[0].version : 0;

    // Run pending migrations
    const pendingMigrations = this.migrations.filter(m => m.version > currentVersion);

    for (const migration of pendingMigrations) {
      console.log(`Running migration ${migration.version}: ${migration.name}`);

      try {
        await migration.up();

        // Record successful migration
        await migrationCollection.insertOne({
          version: migration.version,
          name: migration.name,
          appliedAt: new Date()
        });

        console.log(`Migration ${migration.version} completed successfully`);
      } catch (error) {
        console.error(`Migration ${migration.version} failed:`, error);
        throw error;
      }
    }
  }

  /**
   * Rollback the last migration
   */
  async rollback(): Promise<void> {
    const { db } = await connectToDatabase();
    const migrationCollection = db.collection('migrations');

    const latestMigration = await migrationCollection
      .find()
      .sort({ version: -1 })
      .limit(1)
      .toArray();

    if (!latestMigration.length) {
      console.log('No migrations to roll back');
      return;
    }

    const toRollback = latestMigration[0];
    const migration = this.migrations.find(m => m.version === toRollback.version);

    if (!migration) {
      throw new Error(`Migration ${toRollback.version} not found in registered migrations`);
    }

    console.log(`Rolling back migration ${migration.version}: ${migration.name}`);

    try {
      await migration.down();

      // Remove migration record
      await migrationCollection.deleteOne({ version: migration.version });

      console.log(`Rollback of migration ${migration.version} completed successfully`);
    } catch (error) {
      console.error(`Rollback of migration ${migration.version} failed:`, error);
      throw error;
    }
  }
}

