## Error Handling

Create a utility for consistent error handling in `lib/db/error-handling.ts`:

```typescript
import { MongoError } from 'mongodb';

/**
 * Custom database error class
 */
export class DatabaseError extends Error {
  constructor(
    message: string,
    public code: string,
    public originalError?: Error
  ) {
    super(message);
    this.name = 'DatabaseError';
  }
}

/**
 * Error codes for common database errors
 */
export const ErrorCodes = {
  DUPLICATE_KEY: 'DUPLICATE_KEY',
  NOT_FOUND: 'NOT_FOUND',
  VALIDATION_ERROR: 'VALIDATION_ERROR',
  CONNECTION_ERROR: 'CONNECTION_ERROR',
  UNKNOWN_ERROR: 'UNKNOWN_ERROR'
};

/**
 * Handles MongoDB errors and converts them to more user-friendly errors
 */
export function handleDatabaseError(error: unknown): DatabaseError {
  if (error instanceof MongoError) {
    // Handle MongoDB-specific errors
    switch (error.code) {
      case 11000: // Duplicate key error
        return new DatabaseError(
          'A record with this unique identifier already exists',
          ErrorCodes.DUPLICATE_KEY,
          error
        );

      case 121: // Document validation error
        return new DatabaseError(
          'Data validation failed',
          ErrorCodes.VALIDATION_ERROR,
          error
        );

      default:
        return new DatabaseError(
          error.message,
          ErrorCodes.UNKNOWN_ERROR,
          error
        );
    }
  }

  // Handle general errors
  if (error instanceof Error) {
    if (error.message.includes('connection')) {
      return new DatabaseError(
        'Database connection error',
        ErrorCodes.CONNECTION_ERROR,
        error
      );
    }

    return new DatabaseError(
      error.message,
      ErrorCodes.UNKNOWN_ERROR,
      error
    );
  }

  // Fallback for unknown error types
  return new DatabaseError(
    'Unknown database error',
    ErrorCodes.UNKNOWN_ERROR
  );
}

/**
 * Try-catch wrapper for database operations
 */
export async function withErrorHandling<T>(
  operation: () => Promise<T>,
  customErrorMessage?: string
): Promise<T> {
  try {
    return await operation();
  } catch (error) {
    const dbError = handleDatabaseError(error);
    if (customErrorMessage) {
      dbError.message = customErrorMessage;
    }
    throw dbError;
  }
}
