// Helper function to add a triangle to the STL
function addTriangle(v1, v2, v3) {
  let normal = calculateNormal(v1, v2, v3);

  let triangle = "  facet normal " + normal.join(" ") + "\n";
  triangle += "    outer loop\n";
  triangle += "      vertex " + v1.join(" ") + "\n";
  triangle += "      vertex " + v2.join(" ") + "\n";
  triangle += "      vertex " + v3.join(" ") + "\n";
  triangle += "    endloop\n";
  triangle += "  endfacet\n";

  return triangle;
}

// Calculate normal vector for a triangle
function calculateNormal(v1, v2, v3) {
  const u = [v2[0] - v1[0], v2[1] - v1[1], v2[2] - v1[2]];
  const v = [v3[0] - v1[0], v3[1] - v1[1], v3[2] - v1[2]];

  const normal = [
    u[1] * v[2] - u[2] * v[1],
    u[2] * v[0] - u[0] * v[2],
    u[0] * v[1] - u[1] * v[0]
  ];

  // Normalize
  const length = Math.sqrt(normal[0] * normal[0] + normal[1] * normal[1] + normal[2] * normal[2]);
  if (length === 0) return [0, 0, 1];

  return [normal[0] / length, normal[1] / length, normal[2] / length];
}

// Helper function to add a cube
function addCube(x, y, z, width, height, depth) {
  let cube = "";

  // Define the vertices
  const vertices = [
    [x, y, z],
    [x + width, y, z],
    [x + width, y + height, z],
    [x, y + height, z],
    [x, y, z + depth],
    [x + width, y, z + depth],
    [x + width, y + height, z + depth],
    [x, y + height, z + depth]
  ];

  // Define the faces
  const faces = [
    [0, 1, 2], [0, 2, 3], // Front
    [4, 6, 5], [4, 7, 6], // Back
    [0, 4, 5], [0, 5, 1], // Bottom
    [2, 6, 7], [2, 7, 3], // Top
    [0, 3, 7], [0, 7, 4], // Left
    [1, 5, 6], [1, 6, 2]  // Right
  ];

  // Generate the triangles
  for (const face of faces) {
    cube += addTriangle(vertices[face[0]], vertices[face[1]], vertices[face[2]]);
  }

  return cube;
}

// Helper function to add a cylinder
function addCylinder(x, y, z, radius, height, segments) {
  let cylinder = "";

  // Create top and bottom vertices
  const bottomVertices = [];
  const topVertices = [];

  for (let i = 0; i < segments; i++) {
    const angle = 2 * Math.PI * i / segments;
    const vx = x + radius * Math.cos(angle);
    const vy = y + radius * Math.sin(angle);

    bottomVertices.push([vx, vy, z]);
    topVertices.push([vx, vy, z + height]);
  }

  // Add top and bottom faces
  for (let i = 0; i < segments; i++) {
    const next = (i + 1) % segments;

    // Bottom face
    cylinder += addTriangle(
      [x, y, z],
      bottomVertices[next],
      bottomVertices[i]
    );

    // Top face
    cylinder += addTriangle(
      [x, y, z + height],
      topVertices[i],
      topVertices[next]
    );

    // Side faces
    cylinder += addTriangle(
      bottomVertices[i],
      bottomVertices[next],
      topVertices[i]
    );

    cylinder += addTriangle(
      bottomVertices[next],
      topVertices[next],
      topVertices[i]
    );
  }

  return cylinder;
}

