blade_curve = 0.1;
tsuba_radius = 4;
tsuba_height = 0.8;
handle_length = 15;
handle_width = 1.2;
handle_segments = 8; // For alternating green/black

// Main Module
module katana() {
    // Blade - silver
    blade();

    // Tsuba (hand guard)
    translate([0, 0, 0])
        color("DarkGray")
        cylinder(h=tsuba_height, r=tsuba_radius, $fn=32);

    // Handle with alternating green and black segments
    translate([0, 0, -handle_length-tsuba_height])
        handle();

    // Pommel
    translate([0, 0, -handle_length-tsuba_height-1])
        color("DarkGray")
        cylinder(h=1, r=handle_width*1.5, $fn=32);
}

// Blade Module
module blade() {
    color("Silver")
    union() {
        // Main blade body with curvature
        for (i = [0:blade_length-1]) {
            // Calculate curvature
            y_offset = blade_curve * sin(i/blade_length * 180);
            next_y_offset = blade_curve * sin((i+1)/blade_length * 180);

            // Calculate tapering width
            current_width = blade_width * (1 - 0.7 * i/blade_length);
            next_width = blade_width * (1 - 0.7 * (i+1)/blade_length);

            // Create segment
            hull() {
                translate([0, y_offset, i])
                    scale([current_width, 1, blade_height])
                    cube(1, center=true);

                translate([0, next_y_offset, i+1])
                    scale([next_width, 1, blade_height])
                    cube(1, center=true);
            }
        }

        // Blade tip
        translate([0, blade_curve * sin(180), blade_length])
            rotate([0, 45, 0])
            scale([blade_width * 0.3, 1, blade_height])
            cube(1, center=true);
    }
}

// Handle Module with JP initials
module handle() {
    difference() {
        union() {
            // Base handle with segments for green and black
            for (i = [0:handle_segments-1]) {
                segment_length = handle_length / handle_segments;
                color(i % 2 == 0 ? "ForestGreen" : "Black")
                    translate([0, 0, i * segment_length])
                    cylinder(h=segment_length, r=handle_width * (i % 2 == 0 ? 1.1 : 0.9), $fn=8);
            }
        }

        // Carve "J" on one side
        translate([handle_width*0.6, 0, handle_length*0.25])
            rotate([90, 0, 0])
            linear_extrude(height=handle_width*2)
            text("J", size=handle_width*1.5, halign="center", valign="center", font="Arial:style=Bold");

        // Carve "P" on the opposite side
        translate([-handle_width*0.6, 0, handle_length*0.65])
            rotate([90, 0, 180])
            linear_extrude(height=handle_width*2)
            text("P", size=handle_width*1.5, halign="center", valign="center", font="Arial:style=Bold");
    }

    // Extra wrapping detail
    for (i = [0:handle_segments-2]) {
        segment_length = handle_length / handle_segments;
        color("Black")
            translate([0, 0, i * segment_length + segment_length/2])
            difference() {
                cylinder(h=0.2, r=handle_width*1.2, $fn=8);
                cylinder(h=0.2, r=handle_width*0.8, $fn=8);
            }
    }
}

