 That's excellent that you have ChromaDB set up as a scheduled task to start automatically when your computer starts! This makes your development workflow much smoother for building your Next.js application with ChromaDB integration.

Since ChromaDB is already running automatically, you just need to connect to it from your Next.js application. Here's how you can do that:

1. **Create the ChromaDB client in your Next.js project**:

Create a file at `src/lib/chroma/client.ts`:

```typescript
import { ChromaClient } from 'chromadb';

// Singleton pattern to reuse the same client instance
let client: ChromaClient | null = null;

export function getChromaClient(): ChromaClient {
  if (!client) {
    const host = process.env.CHROMADB_HOST || 'localhost';
    const port = process.env.CHROMADB_PORT || 8000;

    client = new ChromaClient({
      path: `http://${host}:${port}`
    });

    console.log(`ChromaDB client initialized at http://${host}:${port}`);
  }

  return client;
}

// Helper function to get or create a collection
export async function getCollection(name: string) {
  const client = getChromaClient();

  try {
    // Try to get existing collection
    return await client.getCollection({ name });
  } catch (error) {
    // Collection doesn't exist, create it
    console.log(`Creating new collection: ${name}`);
    return await client.createCollection({ name });
  }
}
```

2. **Create a sample API route to verify connection**:

Create a file at `src/app/api/memory/status/route.ts`:

```typescript
import { NextResponse } from 'next/server';
import { getChromaClient } from '@api/lib/chroma/client';

export async function GET() {
  try {
    const client = getChromaClient();
    const heartbeat = await client.heartbeat();
    const collections = await client.listCollections();

    return NextResponse.json({
      status: 'connected',
      heartbeat,
      collections: collections.map(c => c.name)
    });
  } catch (error) {
    console.error('ChromaDB connection error:', error);
    return NextResponse.json({
      status: 'error',
      message: 'Failed to connect to ChromaDB',
      error: error instanceof Error ? error.message : String(error)
    }, { status: 500 });
  }
}
```

3. **Create a memory API route for adding embeddings**:

Create a file at `src/app/api/memory/embed/route.ts`:

```typescript
import { NextResponse } from 'next/server';
import { getCollection } from '@api/lib/chroma/client';

export async function POST(request: Request) {
  try {
    const { collectionName, text, metadata, id } = await request.json();

    if (!collectionName || !text) {
      return NextResponse.json({
        error: 'Missing required fields: collectionName and text'
      }, { status: 400 });
    }

    const collection = await getCollection(collectionName);

    // ChromaDB will automatically generate embeddings using its default embedding function
    await collection.add({
      ids: [id || crypto.randomUUID()],
      documents: [text],
      metadatas: metadata ? [metadata] : undefined
    });

    return NextResponse.json({
      success: true,
      message: 'Memory stored successfully'
    });
  } catch (error) {
    console.error('Error storing memory:', error);
    return NextResponse.json({
      error: 'Failed to store memory',
      message: error instanceof Error ? error.message : String(error)
    }, { status: 500 });
  }
}
```

4. **Create a memory API route for querying embeddings**:

Create a file at `src/app/api/memory/query/route.ts`:

```typescript
import { NextResponse } from 'next/server';
import { getCollection } from '@api/lib/chroma/client';

export async function POST(request: Request) {
  try {
    const { collectionName, queryText, limit = 5, filters } = await request.json();

    if (!collectionName || !queryText) {
      return NextResponse.json({
        error: 'Missing required fields: collectionName and queryText'
      }, { status: 400 });
    }

    const collection = await getCollection(collectionName);

    const results = await collection.query({
      queryTexts: [queryText],
      nResults: limit,
      where: filters
    });

    return NextResponse.json({
      success: true,
      results: {
        ids: results.ids[0],
        documents: results.documents[0],
        metadatas: results.metadatas[0],
        distances: results.distances[0]
      }
    });
  } catch (error) {
    console.error('Error querying memories:', error);
    return NextResponse.json({
      error: 'Failed to query memories',
      message: error instanceof Error ? error.message : String(error)
    }, { status: 500 });
  }
